// Example: A player object moving consistently
class Player {
    constructor() {
        this.x = 100;
        this.y = 100;
        this.speed = 200; // pixels per second
    }

    update(dt) {
        // Move 200 pixels every second, regardless of FPS
        if (keys.ArrowRight) this.x += this.speed * dt;
        if (keys.ArrowLeft) this.x -= this.speed * dt;
        if (keys.ArrowUp) this.y -= this.speed * dt;
        if (keys.ArrowDown) this.y += this.speed * dt;
    }
}

class Game {
    constructor() {
        this.fps = 0;
        this.frameCount = 0;
        this.fpsTimer = 0;
    }

    update(dt) {
        // Update FPS counter every second
        this.frameCount++;
        this.fpsTimer += dt;

        if (this.fpsTimer >= 1) {
            this.fps = this.frameCount;
            this.frameCount = 0;
            this.fpsTimer = 0;
            console.log('FPS:', this.fps);
        }
    }

    draw() {
        // Draw FPS in corner
        this.ctx.fillStyle = '#0f0';
        this.ctx.font = '16px monospace';
        this.ctx.fillText(`FPS: ${this.fps}`, 10, 20);
    }
}

// Fixed time step for physics stability
const FIXED_DT = 1 / 60; // 60 physics updates per second
let accumulator = 0;

function gameLoop(timestamp) {
    const dt = (timestamp - lastTime) / 1000;
    lastTime = timestamp;
    accumulator += dt;

    // Update physics in fixed steps
    while (accumulator >= FIXED_DT) {
        updatePhysics(FIXED_DT);
        accumulator -= FIXED_DT;
    }

    // Interpolate rendering between physics steps
    const alpha = accumulator / FIXED_DT;
    render(alpha);

    requestAnimationFrame(gameLoop);
}

// Input Manager — track key states
class InputManager {
    constructor() {
        this.keys = {};
        this.keysPressed = {}; // For single-press detection

        window.addEventListener('keydown', (e) => {
            this.keys[e.code] = true;
            this.keysPressed[e.code] = true;
        });

        window.addEventListener('keyup', (e) => {
            this.keys[e.code] = false;
        });
    }

    // Check if key is held down
    isDown(code) {
        return !!this.keys[code];
    }

    // Check if key was pressed this frame (one-shot)
    isPressed(code) {
        if (this.keysPressed[code]) {
            this.keysPressed[code] = false;
            return true;
        }
        return false;
    }
}

