class ParallaxLayer {
    constructor(image, speed, width) {
        this.image = image;
        this.speed = speed; // 0 = static, 1 = same as camera
        this.width = width;
        this.offset = 0;
    }

    update(cameraX) {
        this.offset = -(cameraX * this.speed) % this.width;
    }

    draw(ctx) {
        // Draw two copies for seamless looping
        ctx.drawImage(this.image, this.offset, 0);
        ctx.drawImage(this.image, this.offset + this.width, 0);
    }
}

