class Particle {
    constructor(x, y, color) {
        this.x = x;
        this.y = y;
        this.vx = (Math.random() - 0.5) * 200;
        this.vy = (Math.random() - 0.5) * 200;
        this.life = 1.0;
        this.decay = Math.random() * 2 + 1;
        this.color = color;
        this.size = Math.random() * 4 + 2;
    }

    update(dt) {
        this.x += this.vx * dt;
        this.y += this.vy * dt;
        this.life -= this.decay * dt;
        this.size *= 0.98;
    }

    draw(ctx) {
        ctx.globalAlpha = Math.max(this.life, 0);
        ctx.fillStyle = this.color;
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
        ctx.fill();
        ctx.globalAlpha = 1;
    }
}

class ParticleSystem {
    constructor() {
        this.particles = [];
    }

    emit(x, y, count, color) {
        for (let i = 0; i < count; i++) {
            this.particles.push(new Particle(x, y, color));
        }
    }

    update(dt) {
        this.particles.forEach(p => p.update(dt));
        this.particles = this.particles.filter(p => p.life > 0);
    }

    draw(ctx) {
        this.particles.forEach(p => p.draw(ctx));
    }
}

// AABB collision detection
function checkAABB(a, b) {
    return a.x < b.x + b.width &&
           a.x + a.width > b.x &&
           a.y < b.y + b.height &&
           a.y + a.height > b.y;
}

// Usage
const player = { x: 100, y: 100, width: 50, height: 50 };
const enemy = { x: 120, y: 120, width: 40, height: 40 };

if (checkAABB(player, enemy)) {
    console.log('Collision!');
}

// With margin for forgiving gameplay
function checkAABBLoose(a, b, margin = 5) {
    return a.x + margin < b.x + b.width - margin &&
           a.x + a.width - margin > b.x + margin &&
           a.y + margin < b.y + b.height - margin &&
           a.y + a.height - margin > b.y + margin;
}

// Circle collision
function checkCircle(a, b) {
    const dx = a.x - b.x;
    const dy = a.y - b.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    return distance < a.radius + b.radius;
}

// Optimized version (avoid sqrt)
function checkCircleFast(a, b) {
    const dx = a.x - b.x;
    const dy = a.y - b.y;
    const radiusSum = a.radius + b.radius;
    return (dx * dx + dy * dy) < (radiusSum * radiusSum);
}

// Circle vs AABB (for ball hitting paddle)
function checkCircleAABB(circle, rect) {
    // Find closest point on rectangle to circle center
    const closestX = Math.max(rect.x, Math.min(circle.x, rect.x + rect.width));
    const closestY = Math.max(rect.y, Math.min(circle.y, rect.y + rect.height));

    const dx = circle.x - closestX;
    const dy = circle.y - closestY;

    return (dx * dx + dy * dy) < (circle.radius * circle.radius);
}

// Simple bounce response
function resolveBounce(ball, paddle) {
    // Check collision
    if (checkCircleAABB(ball, paddle)) {
        // Determine which side was hit
        const overlapLeft = (ball.x + ball.radius) - paddle.x;
        const overlapRight = (paddle.x + paddle.width) - (ball.x - ball.radius);
        const overlapTop = (ball.y + ball.radius) - paddle.y;
        const overlapBottom = (paddle.y + paddle.height) - (ball.y - ball.radius);

        const minOverlap = Math.min(overlapLeft, overlapRight, overlapTop, overlapBottom);

        // Bounce on the shallowest axis
        if (minOverlap === overlapLeft || minOverlap === overlapRight) {
            ball.vx = -ball.vx;
        } else {
            ball.vy = -ball.vy;
        }

        // Push out of collision
        if (minOverlap === overlapLeft) ball.x = paddle.x - ball.radius;
        if (minOverlap === overlapRight) ball.x = paddle.x + paddle.width + ball.radius;
        if (minOverlap === overlapTop) ball.y = paddle.y - ball.radius;
        if (minOverlap === overlapBottom) ball.y = paddle.y + paddle.height + ball.radius;
    }
}

class SpatialGrid {
    constructor(cellSize) {
        this.cellSize = cellSize;
        this.grid = new Map();
    }

    getKey(x, y) {
        const cx = Math.floor(x / this.cellSize);
        const cy = Math.floor(y / this.cellSize);
        return `${cx},${cy}`;
    }

    insert(obj) {
        const key = this.getKey(obj.x, obj.y);
        if (!this.grid.has(key)) this.grid.set(key, []);
        this.grid.get(key).push(obj);
    }

    clear() {
        this.grid.clear();
    }

    // Get nearby objects for collision checking
    query(obj) {
        const key = this.getKey(obj.x, obj.y);
        return this.grid.get(key) || [];
    }
}

// Usage: Insert all objects, then check only nearby ones
const grid = new SpatialGrid(100);
entities.forEach(e => grid.insert(e));

entities.forEach(entity => {
    const nearby = grid.query(entity);
    nearby.forEach(other => {
        if (entity !== other && checkAABB(entity, other)) {
            handleCollision(entity, other);
        }
    });
});

class AssetManager {
    constructor() {
        this.images = new Map();
        this.audio = new Map();
        this.loading = new Map();
        this.totalAssets = 0;
        this.loadedAssets = 0;
    }

    loadImage(key, src) {
        this.totalAssets++;
        const img = new Image();

        return new Promise((resolve, reject) => {
            img.onload = () => {
                this.images.set(key, img);
                this.loadedAssets++;
                resolve(img);
            };
            img.onerror = () => reject(new Error(`Failed to load: ${src}`));
            img.src = src;
        });
    }

    getImage(key) {
        return this.images.get(key);
    }

    getProgress() {
        return this.totalAssets === 0 ? 1 : this.loadedAssets / this.totalAssets;
    }

    async loadAll(assets) {
        const promises = assets.map(asset => {
            if (asset.type === 'image') {
                return this.loadImage(asset.key, asset.src);
            }
            // Audio loading would go here
        });
        return Promise.all(promises);
    }
}

