class LoadingScreen {
    constructor(canvas, assetManager) {
        this.canvas = canvas;
        this.ctx = canvas.getContext('2d');
        this.assets = assetManager;
    }

    draw() {
        const ctx = this.ctx;
        const w = this.canvas.width;
        const h = this.canvas.height;
        const progress = this.assets.getProgress();

        // Background
        ctx.fillStyle = '#0f0f1e';
        ctx.fillRect(0, 0, w, h);

        // Title
        ctx.fillStyle = '#ecf0f1';
        ctx.font = 'bold 32px Arial';
        ctx.textAlign = 'center';
        ctx.fillText('Loading...', w / 2, h / 2 - 40);

        // Progress bar background
        ctx.fillStyle = '#2c3e50';
        ctx.fillRect(w / 2 - 150, h / 2, 300, 30);

        // Progress bar fill
        ctx.fillStyle = '#e94560';
        ctx.fillRect(w / 2 - 150, h / 2, 300 * progress, 30);

        // Percentage text
        ctx.fillStyle = '#ecf0f1';
        ctx.font = '18px Arial';
        ctx.fillText(`${Math.round(progress * 100)}%`, w / 2, h / 2 + 60);

        return progress >= 1;
    }
}

// Three forms of drawImage
const img = assets.getImage('player');

// 1. Draw full image at position
ctx.drawImage(img, x, y);

// 2. Draw sliced region (sprite sheet)
// drawImage(image, sx, sy, sWidth, sHeight, dx, dy, dWidth, dHeight)
ctx.drawImage(
    img,           // source image
    64, 0, 64, 64, // source x, y, width, height (frame 2)
    x, y, 64, 64   // destination x, y, width, height
);

// 3. Scaled draw (for different resolutions)
ctx.drawImage(img, x, y, 128, 128); // Draw at 2x size

// Optimization: Batch draws by image to reduce context switches
// (Advanced: use offscreen canvas for static backgrounds)
function drawStaticBackground(ctx, bgImage, canvas) {
    // Create offscreen canvas once
    if (!this.offscreen) {
        this.offscreen = document.createElement('canvas');
        this.offscreen.width = canvas.width;
        this.offscreen.height = canvas.height;
        const offCtx = this.offscreen.getContext('2d');
        offCtx.drawImage(bgImage, 0, 0, canvas.width, canvas.height);
    }
    // Draw cached version (much faster!)
    ctx.drawImage(this.offscreen, 0, 0);
}

function draw9Slice(ctx, img, x, y, w, h, border) {
    const bw = border; // border width in source image

    // Corners (no scaling)
    ctx.drawImage(img, 0, 0, bw, bw, x, y, bw, bw); // top-left
    ctx.drawImage(img, img.width - bw, 0, bw, bw, x + w - bw, y, bw, bw); // top-right
    ctx.drawImage(img, 0, img.height - bw, bw, bw, x, y + h - bw, bw, bw); // bottom-left
    ctx.drawImage(img, img.width - bw, img.height - bw, bw, bw, x + w - bw, y + h - bw, bw, bw); // bottom-right

    // Edges (scale 1 axis)
    ctx.drawImage(img, bw, 0, img.width - bw * 2, bw, x + bw, y, w - bw * 2, bw); // top
    ctx.drawImage(img, bw, img.height - bw, img.width - bw * 2, bw, x + bw, y + h - bw, w - bw * 2, bw); // bottom
    ctx.drawImage(img, 0, bw, bw, img.height - bw * 2, x, y + bw, bw, h - bw * 2); // left
    ctx.drawImage(img, img.width - bw, bw, bw, img.height - bw * 2, x + w - bw, y + bw, bw, h - bw * 2); // right

    // Center (scale both axes)
    ctx.drawImage(img, bw, bw, img.width - bw * 2, img.height - bw * 2, x + bw, y + bw, w - bw * 2, h - bw * 2);
}

// Main architecture file: js/pong/Game.js
import { Ball } from './Ball.js';
import { Paddle } from './Paddle.js';
import { InputManager } from './InputManager.js';
import { ScoreBoard } from './ScoreBoard.js';
import { ParticleSystem } from './ParticleSystem.js';

export class PongGame {
    constructor(canvas) {
        this.canvas = canvas;
        this.ctx = canvas.getContext('2d');
        this.width = canvas.width;
        this.height = canvas.height;

        // Subsystems
        this.input = new InputManager();
        this.particles = new ParticleSystem();

        // Game entities
        this.ball = new Ball(this.width / 2, this.height / 2);
        this.playerPaddle = new Paddle(30, this.height / 2, 'player');
        this.aiPaddle = new Paddle(this.width - 50, this.height / 2, 'ai');
        this.scoreBoard = new ScoreBoard();

        // Game state
        this.state = 'menu'; // menu, playing, paused, gameover
        this.maxScore = 10;

        // Timing
        this.lastTime = 0;
    }

    start() {
        this.state = 'playing';
        requestAnimationFrame((t) => this.loop(t));
    }

    loop(timestamp) {
        const dt = Math.min((timestamp - this.lastTime) / 1000, 0.1); // Cap dt
        this.lastTime = timestamp;

        this.update(dt);
        this.draw();

        requestAnimationFrame((t) => this.loop(t));
    }

    update(dt) {
        if (this.state !== 'playing') return;

        this.playerPaddle.update(dt, this.input, this.height);
        this.aiPaddle.updateAI(dt, this.ball, this.height);
        this.ball.update(dt);
        this.particles.update(dt);

        this.checkCollisions();
        this.checkScoring();
    }

    draw() {
        // Clear
        this.ctx.fillStyle = '#0f0f1e';
        this.ctx.fillRect(0, 0, this.width, this.height);

        // Draw center line
        this.ctx.strokeStyle = '#4a4a6a';
        this.ctx.setLineDash([10, 15]);
        this.ctx.beginPath();
        this.ctx.moveTo(this.width / 2, 0);
        this.ctx.lineTo(this.width / 2, this.height);
        this.ctx.stroke();
        this.ctx.setLineDash([]);

        // Draw entities
        this.playerPaddle.draw(this.ctx);
        this.aiPaddle.draw(this.ctx);
        this.ball.draw(this.ctx);
        this.particles.draw(this.ctx);
        this.scoreBoard.draw(this.ctx, this.width);

        // Draw state overlays
        if (this.state === 'menu') this.drawMenu();
        if (this.state === 'paused') this.drawPaused();
        if (this.state === 'gameover') this.drawGameOver();
    }
}

// js/pong/Ball.js
export class Ball {
    constructor(x, y) {
        this.reset(x, y);
        this.radius = 8;
        this.baseSpeed = 400;
        this.maxSpeed = 800;
        this.trail = []; // For motion trail effect
    }

    reset(x, y) {
        this.x = x;
        this.y = y;
        const angle = (Math.random() - 0.5) * Math.PI / 2;
        const direction = Math.random() > 0.5 ? 1 : -1;
        this.vx = Math.cos(angle) * this.baseSpeed * direction;
        this.vy = Math.sin(angle) * this.baseSpeed;
        this.speed = this.baseSpeed;
    }

    update(dt) {
        // Update trail
        this.trail.push({ x: this.x, y: this.y, alpha: 1 });
        if (this.trail.length > 10) this.trail.shift();
        this.trail.forEach(t => t.alpha -= 3 * dt);

        // Move
        this.x += this.vx * dt;
        this.y += this.vy * dt;

        // Wall bounce (top/bottom)
        if (this.y - this.radius < 0 || this.y + this.radius > 600) {
            this.vy = -this.vy;
            this.y = Math.max(this.radius, Math.min(this.y, 600 - this.radius));
        }
    }

    draw(ctx) {
        // Draw trail
        this.trail.forEach(t => {
            ctx.globalAlpha = Math.max(t.alpha, 0);
            ctx.fillStyle = '#e94560';
            ctx.beginPath();
            ctx.arc(t.x, t.y, this.radius * 0.6, 0, Math.PI * 2);
            ctx.fill();
        });
        ctx.globalAlpha = 1;

        // Draw ball
        ctx.fillStyle = '#ecf0f1';
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
        ctx.fill();

        // Glow effect
        ctx.shadowColor = '#e94560';
        ctx.shadowBlur = 15;
        ctx.fill();
        ctx.shadowBlur = 0;
    }

    getBounds() {
        return {
            x: this.x - this.radius,
            y: this.y - this.radius,
            width: this.radius * 2,
            height: this.radius * 2
        };
    }
}

// js/pong/Paddle.js
export class Paddle {
    constructor(x, y, type) {
        this.x = x;
        this.y = y;
        this.width = 15;
        this.height = 100;
        this.type = type; // 'player' or 'ai'
        this.speed = 500;
        this.color = type === 'player' ? '#3498db' : '#e74c3c';
        this.score = 0;
    }

    update(dt, input, canvasHeight) {
        if (this.type === 'player') {
            // Player controls
            if (input.isDown('ArrowUp') || input.isDown('KeyW')) {
                this.y -= this.speed * dt;
            }
            if (input.isDown('ArrowDown') || input.isDown('KeyS')) {
                this.y += this.speed * dt;
            }
        }

        // Clamp to screen
        this.y = Math.max(0, Math.min(this.y, canvasHeight - this.height));
    }

    updateAI(dt, ball, canvasHeight) {
        if (this.type !== 'ai') return;

        // Simple AI: follow ball with reaction delay
        const paddleCenter = this.y + this.height / 2;
        const diff = ball.y - paddleCenter;

        // Only move if ball is moving toward AI
        if (ball.vx > 0) {
            const reactionSpeed = this.speed * 0.75; // Slightly slower than player
            if (Math.abs(diff) > 10) {
                this.y += Math.sign(diff) * reactionSpeed * dt;
            }
        } else {
            // Return to center when ball is moving away
            const centerDiff = (canvasHeight / 2) - paddleCenter;
            this.y += Math.sign(centerDiff) * this.speed * 0.3 * dt;
        }

        this.y = Math.max(0, Math.min(this.y, canvasHeight - this.height));
    }

    draw(ctx) {
        // Main paddle
        ctx.fillStyle = this.color;
        ctx.fillRect(this.x, this.y, this.width, this.height);

        // Highlight edge
        ctx.fillStyle = 'rgba(255,255,255,0.3)';
        ctx.fillRect(this.x, this.y, 3, this.height);

        // Glow
        ctx.shadowColor = this.color;
        ctx.shadowBlur = 10;
        ctx.fillRect(this.x, this.y, this.width, this.height);
        ctx.shadowBlur = 0;
    }

    getBounds() {
        return {
            x: this.x, y: this.y,
            width: this.width, height: this.height
        };
    }
}

// In PongGame class

checkCollisions() {
    const ballBounds = this.ball.getBounds();
    const playerBounds = this.playerPaddle.getBounds();
    const aiBounds = this.aiPaddle.getBounds();

    // Ball vs Player Paddle
    if (this.checkAABB(ballBounds, playerBounds) && this.ball.vx < 0) {
        this.handlePaddleHit(this.playerPaddle);
    }

    // Ball vs AI Paddle
    if (this.checkAABB(ballBounds, aiBounds) && this.ball.vx > 0) {
        this.handlePaddleHit(this.aiPaddle);
    }
}

handlePaddleHit(paddle) {
    // Reverse horizontal direction
    this.ball.vx = -this.ball.vx;

    // Add 'english' (spin effect based on hit position)
    const hitPos = (this.ball.y - (paddle.y + paddle.height / 2)) / (paddle.height / 2);
    this.ball.vy += hitPos * 200;

    // Increase speed slightly
    this.ball.speed = Math.min(this.ball.speed * 1.05, this.ball.maxSpeed);
    const speedRatio = this.ball.speed / Math.sqrt(this.ball.vx ** 2 + this.ball.vy ** 2);
    this.ball.vx *= speedRatio;
    this.ball.vy *= speedRatio;

    // Particles!
    this.particles.emit(this.ball.x, this.ball.y, 20, paddle.color);
}

checkScoring() {
    // Player scores (ball past AI)
    if (this.ball.x > this.width) {
        this.playerPaddle.score++;
        this.ball.reset(this.width / 2, this.height / 2);
        this.particles.emit(this.width - 50, this.height / 2, 50, '#3498db');
        this.checkWin();
    }

    // AI scores (ball past player)
    if (this.ball.x < 0) {
        this.aiPaddle.score++;
        this.ball.reset(this.width / 2, this.height / 2);
        this.particles.emit(50, this.height / 2, 50, '#e74c3c');
        this.checkWin();
    }
}

checkWin() {
    if (this.playerPaddle.score >= this.maxScore || 
        this.aiPaddle.score >= this.maxScore) {
        this.state = 'gameover';
    }
}

// Web Audio API basics
class AudioEngine {
    constructor() {
        this.ctx = new (window.AudioContext || window.webkitAudioContext)();
        this.masterGain = this.ctx.createGain();
        this.masterGain.connect(this.ctx.destination);
        this.masterGain.gain.value = 0.7;

        // Separate channels for music and SFX
        this.musicGain = this.ctx.createGain();
        this.sfxGain = this.ctx.createGain();
        this.musicGain.connect(this.masterGain);
        this.sfxGain.connect(this.masterGain);

        this.musicGain.gain.value = 0.5;
        this.sfxGain.gain.value = 0.8;
    }

    // Resume context (browsers suspend until user interaction)
    async resume() {
        if (this.ctx.state === 'suspended') {
            await this.ctx.resume();
        }
    }

    // Load and decode audio file
    async loadSound(url) {
        const response = await fetch(url);
        const arrayBuffer = await response.arrayBuffer();
        return this.ctx.decodeAudioData(arrayBuffer);
    }

    playSound(buffer, { volume = 1, pan = 0, loop = false } = {}) {
        const source = this.ctx.createBufferSource();
        source.buffer = buffer;
        source.loop = loop;

        // Volume control
        const gain = this.ctx.createGain();
        gain.gain.value = volume;

        // Stereo panning
        const panner = this.ctx.createStereoPanner();
        panner.pan.value = pan;

        // Connect: source → panner → gain → sfx channel
        source.connect(panner);
        panner.connect(gain);
        gain.connect(this.sfxGain);

        source.start();
        return source;
    }
}

class SoundManager {
    constructor() {
        this.engine = new AudioEngine();
        this.sounds = new Map();
        this.musicSource = null;
        this.musicBuffer = null;
    }

    async preload(soundMap) {
        // soundMap = { key: 'path/to/file.wav', ... }
        const entries = Object.entries(soundMap);
        for (const [key, url] of entries) {
            const buffer = await this.engine.loadSound(url);
            this.sounds.set(key, buffer);
        }
    }

    play(key, options = {}) {
        const buffer = this.sounds.get(key);
        if (!buffer) {
            console.warn(`Sound not found: ${key}`);
            return;
        }
        return this.engine.playSound(buffer, options);
    }

    playMusic(key, fadeDuration = 2) {
        const buffer = this.sounds.get(key);
        if (!buffer) return;

        // Fade out current music
        if (this.musicSource) {
            this.fadeOut(this.musicSource, fadeDuration);
        }

        // Start new music
        this.musicBuffer = buffer;
        this.musicSource = this.engine.playSound(buffer, {
            volume: 0,
            loop: true
        });

        // Fade in
        this.fadeIn(this.musicSource, fadeDuration);
    }

    fadeIn(source, duration) {
        const gain = source.context.createGain();
        gain.gain.setValueAtTime(0, this.engine.ctx.currentTime);
        gain.gain.linearRampToValueAtTime(1, this.engine.ctx.currentTime + duration);
    }

    fadeOut(source, duration) {
        const gain = source.context.createGain();
        gain.gain.setValueAtTime(gain.gain.value, this.engine.ctx.currentTime);
        gain.gain.linearRampToValueAtTime(0, this.engine.ctx.currentTime + duration);
        setTimeout(() => source.stop(), duration * 1000);
    }

    setMasterVolume(vol) {
        this.engine.masterGain.gain.value = Math.max(0, Math.min(1, vol));
    }

    setMusicVolume(vol) {
        this.engine.musicGain.gain.value = Math.max(0, Math.min(1, vol));
    }

    setSFXVolume(vol) {
        this.engine.sfxGain.gain.value = Math.max(0, Math.min(1, vol));
    }

    mute() {
        this.engine.masterGain.gain.value = 0;
    }

    unmute() {
        this.engine.masterGain.gain.value = 0.7;
    }
}

// Procedural sound generation
class Synthesizer {
    constructor(audioContext) {
        this.ctx = audioContext;
    }

    // Classic 8-bit jump sound (frequency sweep up)
    jump() {
        const osc = this.ctx.createOscillator();
        const gain = this.ctx.createGain();

        osc.type = 'square';
        osc.frequency.setValueAtTime(150, this.ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(600, this.ctx.currentTime + 0.2);

        gain.gain.setValueAtTime(0.3, this.ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.2);

        osc.connect(gain);
        gain.connect(this.ctx.destination);

        osc.start();
        osc.stop(this.ctx.currentTime + 0.2);
    }

    // Laser shot (frequency sweep down)
    shoot() {
        const osc = this.ctx.createOscillator();
        const gain = this.ctx.createGain();

        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(800, this.ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(100, this.ctx.currentTime + 0.3);

        gain.gain.setValueAtTime(0.2, this.ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.3);

        osc.connect(gain);
        gain.connect(this.ctx.destination);

        osc.start();
        osc.stop(this.ctx.currentTime + 0.3);
    }

    // Explosion (noise burst)
    explosion() {
        const bufferSize = this.ctx.sampleRate * 0.5;
        const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
        const data = buffer.getChannelData(0);

        for (let i = 0; i < bufferSize; i++) {
            data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / bufferSize, 2);
        }

        const source = this.ctx.createBufferSource();
        source.buffer = buffer;

        const gain = this.ctx.createGain();
        gain.gain.setValueAtTime(0.4, this.ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + 0.5);

        // Low-pass filter for muffled explosion sound
        const filter = this.ctx.createBiquadFilter();
        filter.type = 'lowpass';
        filter.frequency.setValueAtTime(1000, this.ctx.currentTime);
        filter.frequency.exponentialRampToValueAtTime(100, this.ctx.currentTime + 0.5);

        source.connect(filter);
        filter.connect(gain);
        gain.connect(this.ctx.destination);

        source.start();
    }
}

// Spatial audio based on screen position
function playSpatialSound(soundKey, worldX, cameraX, canvasWidth) {
    // Calculate relative position (-1 = far left, 1 = far right)
    const screenX = worldX - cameraX;
    const pan = Math.max(-1, Math.min(1, (screenX / canvasWidth) * 2 - 1));

    // Distance attenuation (quieter when farther)
    const distance = Math.abs(screenX - canvasWidth / 2);
    const maxDistance = canvasWidth;
    const volume = Math.max(0.1, 1 - distance / maxDistance);

    soundManager.play(soundKey, { pan, volume });
}

