class PhysicsBody {
    constructor(x, y, mass = 1) {
        this.x = x;
        this.y = y;
        this.vx = 0;
        this.vy = 0;
        this.ax = 0;
        this.ay = 0;
        this.mass = mass;
        this.friction = 0.9;
        this.gravity = 800; // pixels per second squared
        this.grounded = false;
    }

    applyForce(fx, fy) {
        // F = ma, so a = F/m
        this.ax += fx / this.mass;
        this.ay += fy / this.mass;
    }

    update(dt) {
        // Apply gravity
        this.ay += this.gravity;

        // Update velocity (semi-implicit Euler)
        this.vx += this.ax * dt;
        this.vy += this.ay * dt;

        // Apply friction (only when grounded for platformers)
        if (this.grounded) {
            this.vx *= this.friction;
        } else {
            this.vx *= 0.98; // Air resistance
        }

        // Update position
        this.x += this.vx * dt;
        this.y += this.vy * dt;

        // Reset acceleration for next frame
        this.ax = 0;
        this.ay = 0;
    }

    jump() {
        if (this.grounded) {
            this.vy = -500; // Upward impulse
            this.grounded = false;
        }
    }
}

class Platformer extends PhysicsBody {
    constructor(x, y) {
        super(x, y);
        this.width = 32;
        this.height = 48;
        this.jumpTime = 0;
        this.maxJumpTime = 0.2; // Variable jump height
    }

    update(dt, platforms) {
        // Input
        if (input.isDown('ArrowRight')) this.applyForce(2000, 0);
        if (input.isDown('ArrowLeft')) this.applyForce(-2000, 0);

        // Variable jump height: hold longer = jump higher
        if (input.isDown('Space') && this.jumpTime < this.maxJumpTime) {
            this.vy = -400;
            this.jumpTime += dt;
        }
        if (!input.isDown('Space')) {
            this.jumpTime = this.maxJumpTime; // Can't jump anymore
        }

        super.update(dt);

        // Ground collision with platforms
        this.grounded = false;
        for (const platform of platforms) {
            if (this.checkCollision(platform)) {
                // Landing on top
                if (this.vy > 0 && this.y + this.height - this.vy * dt <= platform.y) {
                    this.y = platform.y - this.height;
                    this.vy = 0;
                    this.grounded = true;
                    this.jumpTime = 0;
                }
                // Hitting head
                else if (this.vy < 0 && this.y - this.vy * dt >= platform.y + platform.height) {
                    this.y = platform.y + platform.height;
                    this.vy = 0;
                }
            }
        }

        // Screen boundaries
        this.x = Math.max(0, Math.min(this.x, canvas.width - this.width));
    }

    checkCollision(platform) {
        return this.x < platform.x + platform.width &&
               this.x + this.width > platform.x &&
               this.y < platform.y + platform.height &&
               this.y + this.height > platform.y;
    }
}

class VerletPoint {
    constructor(x, y, pinned = false) {
        this.x = x;
        this.y = y;
        this.oldX = x;
        this.oldY = y;
        this.pinned = pinned;
    }

    update(dt) {
        if (this.pinned) return;

        const vx = (this.x - this.oldX) * 0.99; // Damping
        const vy = (this.y - this.oldY) * 0.99;

        this.oldX = this.x;
        this.oldY = this.y;

        this.x += vx;
        this.y += vy + 500 * dt * dt; // Gravity
    }
}

class VerletStick {
    constructor(p1, p2, length = null) {
        this.p1 = p1;
        this.p2 = p2;
        this.length = length || Math.hypot(p2.x - p1.x, p2.y - p1.y);
    }

    update() {
        const dx = this.p2.x - this.p1.x;
        const dy = this.p2.y - this.p1.y;
        const dist = Math.hypot(dx, dy);
        const diff = this.length - dist;
        const percent = diff / dist / 2;
        const offsetX = dx * percent;
        const offsetY = dy * percent;

        if (!this.p1.pinned) {
            this.p1.x -= offsetX;
            this.p1.y -= offsetY;
        }
        if (!this.p2.pinned) {
            this.p2.x += offsetX;
            this.p2.y += offsetY;
        }
    }
}

// Create a rope
const points = [];
const sticks = [];
for (let i = 0; i < 10; i++) {
