function resolveCollision(a, b) {
    const dx = (a.x + a.width/2) - (b.x + b.width/2);
    const dy = (a.y + a.height/2) - (b.y + b.height/2);
    const overlapX = (a.width + b.width) / 2 - Math.abs(dx);
    const overlapY = (a.height + b.height) / 2 - Math.abs(dy);

    if (overlapX > 0 && overlapY > 0) {
        // Resolve on the shallowest axis
        if (overlapX < overlapY) {
            const dir = dx > 0 ? 1 : -1;
            a.x += overlapX * dir / 2;
            b.x -= overlapX * dir / 2;

            // Bounce
            const tempVx = a.vx;
            a.vx = b.vx * 0.8;
            b.vx = tempVx * 0.8;
        } else {
            const dir = dy > 0 ? 1 : -1;
            a.y += overlapY * dir / 2;
            b.y -= overlapY * dir / 2;

            const tempVy = a.vy;
            a.vy = b.vy * 0.8;
            b.vy = tempVy * 0.8;
        }
    }
}

class TilemapRenderer {
    constructor(tilemap) {
        this.tilemap = tilemap;
    }

    render(ctx, camera) {
        const startCol = Math.floor(camera.x / this.tilemap.tileSize);
        const endCol = startCol + (camera.width / this.tilemap.tileSize) + 1;
        const startRow = Math.floor(camera.y / this.tilemap.tileSize);
        const endRow = startRow + (camera.height / this.tilemap.tileSize) + 1;

        // Clamp to map bounds
        const clampedStartCol = Math.max(0, startCol);
        const clampedEndCol = Math.min(this.tilemap.data.width, endCol);
        const clampedStartRow = Math.max(0, startRow);
        const clampedEndRow = Math.min(this.tilemap.data.height, endRow);

        for (let row = clampedStartRow; row < clampedEndRow; row++) {
            for (let col = clampedStartCol; col < clampedEndCol; col++) {
                const tileId = this.tilemap.data.layers.background[row][col];
                if (tileId === 0) continue; // Empty tile

                const worldX = col * this.tilemap.tileSize;
                const worldY = row * this.tilemap.tileSize;
                const screenX = worldX - camera.x;
                const screenY = worldY - camera.y;

                this.drawTile(ctx, tileId, screenX, screenY);
            }
        }
    }

    drawTile(ctx, tileId, x, y) {
        // Convert tile ID to tileset coordinates
        const tilesPerRow = this.tilemap.tileset.width / this.tilemap.tileSize;
        const srcX = (tileId % tilesPerRow) * this.tilemap.tileSize;
        const srcY = Math.floor(tileId / tilesPerRow) * this.tilemap.tileSize;

        ctx.drawImage(
            this.tilemap.tileset,
            srcX, srcY, this.tilemap.tileSize, this.tilemap.tileSize,
            x, y, this.tilemap.tileSize, this.tilemap.tileSize
        );
    }
}

// Parse Tiled JSON export
class TiledLoader {
    static async load(url) {
        const response = await fetch(url);
        const data = await response.json();

        return {
            width: data.width,
            height: data.height,
            tileSize: data.tilewidth,
            layers: this.parseLayers(data.layers),
            tilesets: data.tilesets
        };
    }

    static parseLayers(layers) {
        const result = {};
        layers.forEach(layer => {
            if (layer.type === 'tilelayer') {
                // Convert 1D array to 2D
                result[layer.name] = [];
                for (let y = 0; y < layer.height; y++) {
                    const row = [];
                    for (let x = 0; x < layer.width; x++) {
                        // Tiled uses 1-based IDs, subtract 1 for 0-based
                        row.push(layer.data[y * layer.width + x] - 1);
                    }
                    result[layer.name].push(row);
                }
            } else if (layer.type === 'objectgroup') {
                // Spawn points, triggers, etc.
                result.objects = layer.objects;
            }
        });
        return result;
    }
}

