shake.apply(ctx, camera);

class ZoomCamera extends SmoothCamera {
    constructor(viewWidth, viewHeight) {
        super(viewWidth, viewHeight);
        this.zoom = 1;
        this.targetZoom = 1;
        this.minZoom = 0.5;
        this.maxZoom = 2;
        this.zoomSpeed = 3;
    }

    update(target, dt) {
        super.update(target, dt);

        // Smooth zoom
        this.zoom += (this.targetZoom - this.zoom) * this.zoomSpeed * dt;
        this.zoom = Math.max(this.minZoom, Math.min(this.maxZoom, this.zoom));
    }

    apply(ctx) {
        ctx.save();

        // Zoom from center of screen
        const centerX = this.viewWidth / 2;
        const centerY = this.viewHeight / 2;

        ctx.translate(centerX, centerY);
        ctx.scale(this.zoom, this.zoom);
        ctx.translate(-centerX - this.x, -centerY - this.y);
    }

    setZoom(zoomLevel) {
        this.targetZoom = zoomLevel;
    }

    // Zoom to show specific area
    zoomToFit(minX, minY, maxX, maxY) {
        const contentWidth = maxX - minX;
        const contentHeight = maxY - minY;
        const zoomX = this.viewWidth / contentWidth;
        const zoomY = this.viewHeight / contentHeight;
        this.targetZoom = Math.min(zoomX, zoomY) * 0.9; // 10% padding
    }
}

class MultiTargetCamera extends ZoomCamera {
    constructor(viewWidth, viewHeight) {
        super(viewWidth, viewHeight);
        this.targets = [];
        this.padding = 100;
    }

    addTarget(target) {
        this.targets.push(target);
    }

    update(dt) {
        if (this.targets.length === 0) return;

        // Calculate bounding box of all targets
        let minX = Infinity, minY = Infinity;
        let maxX = -Infinity, maxY = -Infinity;

        this.targets.forEach(t => {
            minX = Math.min(minX, t.x);
            minY = Math.min(minY, t.y);
            maxX = Math.max(maxX, t.x);
            maxY = Math.max(maxY, t.y);
        });

        // Center on midpoint
        const midX = (minX + maxX) / 2;
        const midY = (minY + maxY) / 2;

        // Zoom to fit all targets
        const contentWidth = maxX - minX + this.padding * 2;
        const contentHeight = maxY - minY + this.padding * 2;
        const zoomX = this.viewWidth / contentWidth;
        const zoomY = this.viewHeight / contentHeight;
        this.targetZoom = Math.min(zoomX, zoomY, this.maxZoom);

        // Smoothly move to center
        const targetX = midX - this.viewWidth / (2 * this.zoom);
        const targetY = midY - this.viewHeight / (2 * this.zoom);

        this.x += (targetX - this.x) * this.smoothing;
        this.y += (targetY - this.y) * this.smoothing;

        super.update(null, dt); // Apply zoom smoothing
    }
}

// In FlappyGame class

handleInput() {
    const jump = () => {
        if (this.state === 'menu') {
            this.state = 'playing';
            this.bird.jump();
        } else if (this.state === 'playing') {
            this.bird.jump();
        } else if (this.state === 'gameover') {
            this.reset();
            this.state = 'menu';
        }
    };

    // Mouse/touch
    this.canvas.addEventListener('mousedown', jump);
    this.canvas.addEventListener('touchstart', (e) => {
        e.preventDefault();
        jump();
    });

    // Keyboard
    window.addEventListener('keydown', (e) => {
        if (e.code === 'Space') jump();
    });
}

gameOver() {
    this.state = 'gameover';
    this.shake.addTrauma(0.6);
    this.particles.emit(this.bird.x, this.bird.y, 30, '#FFD700');

    // Save high score
    if (this.score.value > this.highScore) {
        this.highScore = this.score.value;
        localStorage.setItem('flappyHighScore', this.highScore);
    }
}

loadHighScore() {
    return parseInt(localStorage.getItem('flappyHighScore')) || 0;
}

reset() {
    this.bird = new Bird(100, this.height / 2);
    this.pipeManager.reset();
    this.score.reset();
    this.scrollSpeed = 200;
}

drawGameOver() {
    const ctx = this.ctx;
    const cx = this.width / 2;
    const cy = this.height / 2;

    // Dark overlay
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(0, 0, this.width, this.height);

    // Score board
    ctx.fillStyle = '#DED895';
    ctx.fillRect(cx - 120, cy - 100, 240, 200);
    ctx.strokeStyle = '#5C4018';
    ctx.lineWidth = 4;
    ctx.strokeRect(cx - 120, cy - 100, 240, 200);

    // Game Over text
    ctx.fillStyle = '#E74C3C';
    ctx.font = 'bold 36px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('GAME OVER', cx, cy - 60);

    // Score
    ctx.fillStyle = '#FFF';
    ctx.font = '24px Arial';
    ctx.fillText(`Score: ${this.score.value}`, cx, cy - 10);
    ctx.fillText(`Best: ${this.highScore}`, cx, cy + 30);

    // Medal
    const medal = this.getMedal();
    if (medal) {
        ctx.fillStyle = medal.color;
        ctx.beginPath();
        ctx.arc(cx, cy + 80, 25, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#FFF';
        ctx.lineWidth = 3;
        ctx.stroke();
        ctx.fillStyle = '#FFF';
        ctx.font = 'bold 16px Arial';
        ctx.fillText(medal.label, cx, cy + 86);
    }

    // Restart hint
    ctx.fillStyle = '#FFF';
    ctx.font = '18px Arial';
    ctx.fillText('Tap to restart', cx, cy + 140);
}

getMedal() {
    const s = this.score.value;
    if (s >= 40) return { color: '#FFD700', label: 'GOLD' };
    if (s >= 30) return { color: '#C0C0C0', label: 'SILVER' };
    if (s >= 20) return { color: '#CD7F32', label: 'BRONZE' };
    return null;
}

// Base state interface
class GameState {
    constructor(game) {
        this.game = game;
    }
    enter() {}      // Called when entering state
    update(dt) {}   // Return new state or null to stay
    draw(ctx) {}
    exit() {}       // Called when leaving state
    handleInput(input) {}
}

// State Manager
class StateMachine {
    constructor() {
        this.currentState = null;
        this.states = new Map();
    }

    register(name, StateClass) {
        this.states.set(name, StateClass);
    }

    change(name, ...args) {
        if (this.currentState) {
            this.currentState.exit();
        }

        const StateClass = this.states.get(name);
        this.currentState = new StateClass(this.game, ...args);
        this.currentState.enter();
    }

    update(dt) {
        if (!this.currentState) return;
        const nextState = this.currentState.update(dt);
        if (nextState) {
            this.change(nextState);
        }
    }

    draw(ctx) {
        if (this.currentState) {
            this.currentState.draw(ctx);
        }
    }
}

class MenuState extends GameState {
    enter() {
        this.menuItems = ['Start', 'Options', 'Quit'];
        this.selected = 0;
    }

    update(dt) {
        // Animate background
        this.game.bgStars.update(dt);
        return null; // Stay in menu
    }

    draw(ctx) {
        this.game.bgStars.draw(ctx);

        ctx.fillStyle = '#FFF';
        ctx.font = 'bold 48px Arial';
        ctx.textAlign = 'center';
        ctx.fillText('MY GAME', this.game.width / 2, 150);

        // Menu items
        ctx.font = '24px Arial';
        this.menuItems.forEach((item, i) => {
            ctx.fillStyle = i === this.selected ? '#FFD700' : '#AAA';
            ctx.fillText(item, this.game.width / 2, 300 + i * 50);
        });
    }

    handleInput(input) {
        if (input.isPressed('ArrowDown')) {
            this.selected = (this.selected + 1) % this.menuItems.length;
        }
        if (input.isPressed('ArrowUp')) {
            this.selected = (this.selected - 1 + this.menuItems.length) % this.menuItems.length;
        }
        if (input.isPressed('Enter')) {
            if (this.selected === 0) return 'playing';
            if (this.selected === 2) this.game.quit();
        }
        return null;
    }
}

class PlayingState extends GameState {
    enter() {
        this.game.world.reset();
        this.game.player.reset();
    }

    update(dt) {
        if (input.isPressed('Escape')) {
            return 'paused';
        }

        this.game.world.update(dt);
        this.game.player.update(dt);

        if (this.game.player.health <= 0) {
            return 'gameover';
        }

        return null;
    }

    draw(ctx) {
        this.game.world.draw(ctx);
        this.game.player.draw(ctx);
        this.game.ui.drawHUD(ctx);
    }
}

class PauseState extends GameState {
    enter() {
        this.game.audio.pauseMusic();
    }

    exit() {
        this.game.audio.resumeMusic();
    }

    update(dt) {
        return null; // Frozen
    }

    draw(ctx) {
        // Draw game behind (frozen)
        this.game.states.get('playing').draw(ctx);

        // Dark overlay
        ctx.fillStyle = 'rgba(0,0,0,0.6)';
        ctx.fillRect(0, 0, this.game.width, this.game.height);

        ctx.fillStyle = '#FFF';
        ctx.font = 'bold 36px Arial';
        ctx.textAlign = 'center';
        ctx.fillText('PAUSED', this.game.width / 2, this.game.height / 2);
    }

    handleInput(input) {
        if (input.isPressed('Escape') || input.isPressed('Enter')) {
            return 'playing';
        }
        return null;
    }
}

