class MovementSystem {
    update(world, dt) {
        const positions = world.components.get('position');
        const velocities = world.components.get('velocity');

        if (!positions || !velocities) return;

        for (const [entityId, pos] of positions) {
            const vel = velocities.get(entityId);
            if (!vel) continue;

            pos.x += vel.vx * dt;
            pos.y += vel.vy * dt;

            // Apply friction
            vel.vx *= 0.98;
            vel.vy *= 0.98;
        }
    }
}

class RenderSystem {
    draw(world, ctx) {
        const positions = world.components.get('position');
        const sprites = world.components.get('sprite');

        if (!positions || !sprites) return;

        for (const [entityId, pos] of positions) {
            const sprite = sprites.get(entityId);
            if (!sprite) continue;

            ctx.drawImage(
                sprite.image,
                pos.x - sprite.width / 2,
                pos.y - sprite.height / 2,
                sprite.width,
                sprite.height
            );
        }
    }
}

class CollisionSystem {
    update(world, dt) {
        const positions = world.components.get('position');
        const colliders = world.components.get('collider');
        const healths = world.components.get('health');

        if (!positions || !colliders) return;

        const entities = Array.from(positions.keys())
            .filter(id => colliders.has(id));

        // O(n²) — use spatial hashing for many entities
        for (let i = 0; i < entities.length; i++) {
            for (let j = i + 1; j < entities.length; j++) {
                const id1 = entities[i];
                const id2 = entities[j];

                if (this.checkCollision(positions, colliders, id1, id2)) {
                    this.handleCollision(world, id1, id2);
                }
            }
        }
    }

    checkCollision(positions, colliders, id1, id2) {
        const p1 = positions.get(id1);
        const c1 = colliders.get(id1);
        const p2 = positions.get(id2);
        const c2 = colliders.get(id2);

        return p1.x < p2.x + c2.width && p1.x + c1.width > p2.x &&
               p1.y < p2.y + c2.height && p1.y + c1.height > p2.y;
    }

    handleCollision(world, id1, id2) {
        const player = world.getComponent(id1, 'player');
        const enemy = world.getComponent(id2, 'enemy');

        if (player && enemy) {
            const health = world.getComponent(id1, 'health');
            if (health) health.current -= 10;
        }
    }
}

class EnemyAI {
    constructor(enemy, player) {
        this.enemy = enemy;
        this.player = player;
        this.state = 'patrol';
        this.patrolPoints = [{x: 100, y: 200}, {x: 300, y: 200}];
        this.currentPoint = 0;
        this.visionRange = 200;
        this.attackRange = 40;
    }

    update(dt) {
        const distToPlayer = Math.hypot(
            this.player.x - this.enemy.x,
            this.player.y - this.enemy.y
        );

        switch (this.state) {
            case 'patrol':
                this.patrol(dt);
                if (distToPlayer < this.visionRange) {
                    this.state = 'chase';
                }
                break;

            case 'chase':
                this.chase(dt);
                if (distToPlayer < this.attackRange) {
                    this.state = 'attack';
                } else if (distToPlayer > this.visionRange * 1.5) {
                    this.state = 'patrol';
                }
                break;

            case 'attack':
                this.attack(dt);
                if (distToPlayer > this.attackRange * 1.5) {
                    this.state = 'chase';
                }
                if (this.enemy.health < 20) {
                    this.state = 'flee';
                }
                break;

            case 'flee':
                this.flee(dt);
                if (distToPlayer > this.visionRange * 2) {
                    this.state = 'patrol';
                }
                break;
        }
    }

    patrol(dt) {
        const target = this.patrolPoints[this.currentPoint];
        this.moveTo(target, 50, dt);

        if (Math.hypot(target.x - this.enemy.x, target.y - this.enemy.y) < 5) {
            this.currentPoint = (this.currentPoint + 1) % this.patrolPoints.length;
        }
    }

    chase(dt) {
        this.moveTo(this.player, 120, dt);
    }

    attack(dt) {
        this.enemy.attack();
        // Small recoil
        this.enemy.x -= Math.cos(this.enemy.angle) * 2;
    }

    flee(dt) {
        // Move away from player
        const angle = Math.atan2(
            this.enemy.y - this.player.y,
            this.enemy.x - this.player.x
        );
        this.enemy.x += Math.cos(angle) * 100 * dt;
        this.enemy.y += Math.sin(angle) * 100 * dt;
    }

    moveTo(target, speed, dt) {
        const angle = Math.atan2(target.y - this.enemy.y, target.x - this.enemy.x);
        this.enemy.x += Math.cos(angle) * speed * dt;
        this.enemy.y += Math.sin(angle) * speed * dt;
        this.enemy.angle = angle;
    }
}

class AStar {
    static findPath(grid, start, end) {
        const openSet = [start];
        const closedSet = new Set();
        const cameFrom = new Map();
        const gScore = new Map();
        const fScore = new Map();

        gScore.set(this.key(start), 0);
        fScore.set(this.key(start), this.heuristic(start, end));

        while (openSet.length > 0) {
            // Get node with lowest fScore
            openSet.sort((a, b) => 
                (fScore.get(this.key(a)) || Infinity) - 
                (fScore.get(this.key(b)) || Infinity)
            );
            const current = openSet.shift();

            if (current.x === end.x && current.y === end.y) {
                return this.reconstructPath(cameFrom, current);
            }

            closedSet.add(this.key(current));

            for (const neighbor of this.getNeighbors(grid, current)) {
                if (closedSet.has(this.key(neighbor))) continue;

                const tentativeG = (gScore.get(this.key(current)) || 0) + 1;

                if (!openSet.some(n => n.x === neighbor.x && n.y === neighbor.y)) {
                    openSet.push(neighbor);
                } else if (tentativeG >= (gScore.get(this.key(neighbor)) || Infinity)) {
                    continue;
                }

                cameFrom.set(this.key(neighbor), current);
                gScore.set(this.key(neighbor), tentativeG);
                fScore.set(this.key(neighbor), tentativeG + this.heuristic(neighbor, end));
            }
        }

        return null; // No path found
    }

    static heuristic(a, b) {
        // Manhattan distance for grid
        return Math.abs(a.x - b.x) + Math.abs(a.y - b.y);
    }

    static key(node) {
        return `${node.x},${node.y}`;
    }

    static getNeighbors(grid, node) {
        const neighbors = [];
        const dirs = [[0,1], [0,-1], [1,0], [-1,0]];

        for (const [dx, dy] of dirs) {
            const nx = node.x + dx;
            const ny = node.y + dy;
            if (grid[ny]?.[nx] === 0) { // 0 = walkable
                neighbors.push({x: nx, y: ny});
            }
        }
        return neighbors;
    }

    static reconstructPath(cameFrom, current) {
        const path = [current];
        while (cameFrom.has(this.key(current))) {
            current = cameFrom.get(this.key(current));
            path.unshift(current);
        }
        return path;
    }
}

class Steering {
    static seek(agent, target, maxSpeed = 200, maxForce = 100) {
        const desired = {
            x: target.x - agent.x,
            y: target.y - agent.y
        };
        const dist = Math.hypot(desired.x, desired.y);

        if (dist > 0) {
            desired.x = (desired.x / dist) * maxSpeed;
            desired.y = (desired.y / dist) * maxSpeed;
        }

        const steer = {
            x: desired.x - agent.vx,
            y: desired.y - agent.vy
        };

        // Clamp force
        const steerMag = Math.hypot(steer.x, steer.y);
        if (steerMag > maxForce) {
            steer.x = (steer.x / steerMag) * maxForce;
            steer.y = (steer.y / steerMag) * maxForce;
        }

        return steer;
    }

    static flee(agent, target, maxSpeed, maxForce) {
        const desired = {
            x: agent.x - target.x,
            y: agent.y - target.y
        };
        const dist = Math.hypot(desired.x, desired.y);

        if (dist > 0 && dist < 150) { // Only flee if close
            desired.x = (desired.x / dist) * maxSpeed;
            desired.y = (desired.y / dist) * maxSpeed;

            return {
                x: Math.max(-maxForce, Math.min(maxForce, desired.x - agent.vx)),
                y: Math.max(-maxForce, Math.min(maxForce, desired.y - agent.vy))
            };
        }
        return {x: 0, y: 0};
    }

    static wander(agent, wanderRadius = 50, wanderDistance = 100, wanderJitter = 20) {
        // Random point on circle ahead of agent
        const circleCenter = {
            x: agent.x + Math.cos(agent.angle) * wanderDistance,
            y: agent.y + Math.sin(agent.angle) * wanderDistance
        };

        const wanderAngle = Math.random() * Math.PI * 2;
        const target = {
            x: circleCenter.x + Math.cos(wanderAngle) * wanderRadius,
            y: circleCenter.y + Math.sin(wanderAngle) * wanderRadius
        };

        return this.seek(agent, target, 100, 50);
    }

    static separation(agent, neighbors, desiredSeparation = 30) {
        const steer = {x: 0, y: 0};
        let count = 0;

        for (const other of neighbors) {
            const dx = agent.x - other.x;
            const dy = agent.y - other.y;
            const dist = Math.hypot(dx, dy);

            if (dist > 0 && dist < desiredSeparation) {
                steer.x += dx / dist;
                steer.y += dy / dist;
                count++;
            }
        }

        if (count > 0) {
            steer.x /= count;
            steer.y /= count;
        }

        return steer;
    }
}

class Boid {
    update(dt, allBoids) {
        const neighbors = allBoids.filter(b => b !== this && 
            Math.hypot(b.x - this.x, b.y - this.y) < 100);

        const sep = Steering.separation(this, neighbors, 25);
        const ali = this.alignment(neighbors);
        const coh = this.cohesion(neighbors);
        const wan = Steering.wander(this);

        // Weighted combination
        this.vx += sep.x * 1.5 + ali.x * 1.0 + coh.x * 1.0 + wan.x * 0.5;
        this.vy += sep.y * 1.5 + ali.y * 1.0 + coh.y * 1.0 + wan.y * 0.5;

        // Limit speed
        const speed = Math.hypot(this.vx, this.vy);
        if (speed > this.maxSpeed) {
            this.vx = (this.vx / speed) * this.maxSpeed;
            this.vy = (this.vy / speed) * this.maxSpeed;
        }

        this.x += this.vx * dt;
        this.y += this.vy * dt;
        this.angle = Math.atan2(this.vy, this.vx);
    }

    alignment(neighbors) {
        if (neighbors.length === 0) return {x: 0, y: 0};
        let avgVx = 0, avgVy = 0;
        neighbors.forEach(n => { avgVx += n.vx; avgVy += n.vy; });
        return {
            x: (avgVx / neighbors.length - this.vx) * 0.05,
            y: (avgVy / neighbors.length - this.vy) * 0.05
        };
    }

    cohesion(neighbors) {
        if (neighbors.length === 0) return {x: 0, y: 0};
        let avgX = 0, avgY = 0;
        neighbors.forEach(n => { avgX += n.x; avgY += n.y; });
        return Steering.seek(this, {x: avgX / neighbors.length, y: avgY / neighbors.length}, 100, 50);
    }
}

class UIElement {
    constructor(x, y, width, height) {
        this.x = x;
        this.y = y;
        this.width = width;
        this.height = height;
        this.visible = true;
        this.enabled = true;
        this.hovered = false;
        this.parent = null;
        this.children = [];
    }

    addChild(child) {
        child.parent = this;
        this.children.push(child);
    }

    getAbsolutePosition() {
        if (!this.parent) return {x: this.x, y: this.y};
        const parentPos = this.parent.getAbsolutePosition();
        return {x: parentPos.x + this.x, y: parentPos.y + this.y};
    }

    containsPoint(px, py) {
        const pos = this.getAbsolutePosition();
        return px >= pos.x && px <= pos.x + this.width &&
               py >= pos.y && py <= pos.y + this.height;
    }

    update(dt) {
        for (const child of this.children) {
            if (child.visible) child.update(dt);
        }
    }

    draw(ctx) {
        if (!this.visible) return;
        this.drawSelf(ctx);
        for (const child of this.children) {
            child.draw(ctx);
        }
    }

    drawSelf(ctx) {} // Override in subclasses

    handleMouseMove(x, y) {
        this.hovered = this.containsPoint(x, y);
        for (const child of this.children) {
            child.handleMouseMove(x, y);
        }
    }

    handleClick(x, y) {
        if (!this.enabled || !this.visible) return false;

        for (const child of this.children) {
            if (child.handleClick(x, y)) return true;
        }

        if (this.containsPoint(x, y)) {
            this.onClick?.();
            return true;
        }
        return false;
    }
}

class Button extends UIElement {
    constructor(x, y, width, height, text, onClick) {
        super(x, y, width, height);
        this.text = text;
        this.onClick = onClick;
        this.pressed = false;
        this.colors = {
            normal: '#3498db',
            hover: '#2980b9',
            pressed: '#1a5276',
            text: '#ffffff'
        };
    }

    drawSelf(ctx) {
        const pos = this.getAbsolutePosition();
        let color = this.colors.normal;
        if (this.pressed) color = this.colors.pressed;
        else if (this.hovered) color = this.colors.hover;

        // Background with rounded corners
        ctx.fillStyle = color;
        this.roundRect(ctx, pos.x, pos.y, this.width, this.height, 8);
        ctx.fill();

        // Shadow for depth
        if (!this.pressed) {
            ctx.fillStyle = 'rgba(0,0,0,0.2)';
            this.roundRect(ctx, pos.x, pos.y + 3, this.width, this.height, 8);
            ctx.fill();
        }

        // Text
        ctx.fillStyle = this.colors.text;
        ctx.font = 'bold 16px Arial';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(this.text, pos.x + this.width / 2, pos.y + this.height / 2);
    }

    roundRect(ctx, x, y, w, h, r) {
        ctx.beginPath();
        ctx.moveTo(x + r, y);
        ctx.lineTo(x + w - r, y);
        ctx.quadraticCurveTo(x + w, y, x + w, y + r);
        ctx.lineTo(x + w, y + h - r);
        ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
        ctx.lineTo(x + r, y + h);
        ctx.quadraticCurveTo(x, y + h, x, y + h - r);
        ctx.lineTo(x, y + r);
        ctx.quadraticCurveTo(x, y, x + r, y);
        ctx.closePath();
    }
}

class ProgressBar extends UIElement {
    constructor(x, y, width, height, maxValue) {
        super(x, y, width, height);
        this.value = maxValue;
        this.maxValue = maxValue;
        this.displayValue = maxValue;
        this.colors = {
            background: '#2c3e50',
            fill: '#e74c3c',
            low: '#c0392b'
        };
    }

    update(dt) {
        super.update(dt);
        // Smooth animation
        this.displayValue += (this.value - this.displayValue) * 10 * dt;
    }

    drawSelf(ctx) {
        const pos = this.getAbsolutePosition();
        const ratio = Math.max(0, this.displayValue / this.maxValue);

        // Background
        ctx.fillStyle = this.colors.background;
        ctx.fillRect(pos.x, pos.y, this.width, this.height);

        // Fill
        ctx.fillStyle = ratio < 0.2 ? this.colors.low : this.colors.fill;
        ctx.fillRect(pos.x, pos.y, this.width * ratio, this.height);

        // Border
        ctx.strokeStyle = '#34495e';
        ctx.lineWidth = 2;
        ctx.strokeRect(pos.x, pos.y, this.width, this.height);
    }

    setValue(v) {
        this.value = Math.max(0, Math.min(v, this.maxValue));
    }
}

class Slider extends UIElement {
    constructor(x, y, width, min, max, value, onChange) {
        super(x, y, width, 20);
        this.min = min;
        this.max = max;
        this.value = value;
        this.onChange = onChange;
        this.dragging = false;
        this.handleWidth = 16;
    }

    drawSelf(ctx) {
        const pos = this.getAbsolutePosition();
        const ratio = (this.value - this.min) / (this.max - this.min);
        const handleX = pos.x + ratio * (this.width - this.handleWidth);

        // Track
        ctx.fillStyle = '#34495e';
        ctx.fillRect(pos.x, pos.y + 7, this.width, 6);

        // Handle
        ctx.fillStyle = this.dragging ? '#3498db' : '#5dade2';
        ctx.fillRect(handleX, pos.y, this.handleWidth, this.height);
        ctx.strokeStyle = '#2980b9';
        ctx.lineWidth = 2;
        ctx.strokeRect(handleX, pos.y, this.handleWidth, this.height);
    }

    handleMouseDown(x, y) {
        if (this.containsPoint(x, y)) {
            this.dragging = true;
            this.updateValue(x);
            return true;
        }
        return false;
    }

    handleMouseMove(x, y) {
        if (this.dragging) {
            this.updateValue(x);
        }
        return super.handleMouseMove(x, y);
    }

    updateValue(mouseX) {
        const pos = this.getAbsolutePosition();
        const ratio = Math.max(0, Math.min(1, 
            (mouseX - pos.x) / (this.width - this.handleWidth)));
        this.value = this.min + ratio * (this.max - this.min);
        this.onChange?.(this.value);
    }

    handleMouseUp() {
        this.dragging = false;
    }
}

class TextRenderer {
    static drawWrappedText(ctx, text, x, y, maxWidth, lineHeight, align = 'left') {
        const words = text.split(' ');
        let line = '';
        const lines = [];

        for (const word of words) {
            const testLine = line + word + ' ';
            const metrics = ctx.measureText(testLine);
            if (metrics.width > maxWidth && line !== '') {
                lines.push(line.trim());
                line = word + ' ';
            } else {
                line = testLine;
            }
        }
        lines.push(line.trim());

        // Draw lines
        ctx.textBaseline = 'top';
        lines.forEach((line, i) => {
            let drawX = x;
            if (align === 'center') {
                drawX = x + (maxWidth - ctx.measureText(line).width) / 2;
            } else if (align === 'right') {
                drawX = x + maxWidth - ctx.measureText(line).width;
            }
            ctx.fillText(line, drawX, y + i * lineHeight);
        });

        return lines.length * lineHeight;
    }

    static drawTextWithShadow(ctx, text, x, y, options = {}) {
        const {
            color = '#fff',
            shadowColor = 'rgba(0,0,0,0.5)',
            shadowBlur = 4,
            shadowOffsetX = 2,
            shadowOffsetY = 2,
            font = '16px Arial'
        } = options;

        ctx.font = font;
        ctx.save();
        ctx.shadowColor = shadowColor;
        ctx.shadowBlur = shadowBlur;
        ctx.shadowOffsetX = shadowOffsetX;
        ctx.shadowOffsetY = shadowOffsetY;
        ctx.fillStyle = color;
        ctx.fillText(text, x, y);
        ctx.restore();
    }
}

class Tooltip extends UIElement {
    constructor() {
        super(0, 0, 200, 60);
        this.text = '';
        this.visible = false;
        this.padding = 10;
    }

    show(text, x, y, canvasWidth, canvasHeight) {
        this.text = text;
        this.visible = true;

        // Measure text to size tooltip
        const ctx = document.createElement('canvas').getContext('2d');
        ctx.font = '14px Arial';
        const lines = text.split('\n');
        let maxWidth = 0;
        lines.forEach(line => {
            maxWidth = Math.max(maxWidth, ctx.measureText(line).width);
        });

        this.width = maxWidth + this.padding * 2;
        this.height = lines.length * 20 + this.padding * 2;

        // Position with screen edge checking
        this.x = x + 15;
        this.y = y + 15;
        if (this.x + this.width > canvasWidth) this.x = x - this.width - 15;
        if (this.y + this.height > canvasHeight) this.y = y - this.height - 15;
    }

    hide() {
        this.visible = false;
    }

    drawSelf(ctx) {
        const pos = this.getAbsolutePosition();

        // Background
        ctx.fillStyle = 'rgba(0, 0, 0, 0.9)';
        ctx.strokeStyle = '#5dade2';
        ctx.lineWidth = 1;
        ctx.fillRect(pos.x, pos.y, this.width, this.height);
        ctx.strokeRect(pos.x, pos.y, this.width, this.height);

        // Text
        ctx.fillStyle = '#ecf0f1';
        ctx.font = '14px Arial';
        ctx.textBaseline = 'top';
        this.text.split('\n').forEach((line, i) => {
            ctx.fillText(line, pos.x + this.padding, pos.y + this.padding + i * 20);
        });
    }
}

// js/platformer/World.js
import { Tilemap } from './Tilemap.js';
import { EntityManager } from './EntityManager.js';
import { ParticleSystem } from './ParticleSystem.js';

export class World {
    constructor() {
        this.tilemap = null;
        this.entities = new EntityManager();
        this.particles = new ParticleSystem();
        this.width = 0;
        this.height = 0;
        this.spawnPoint = { x: 100, y: 100 };
    }

    load(levelData) {
        this.tilemap = new Tilemap(levelData.tilemap);
        this.width = this.tilemap.width * this.tilemap.tileSize;
        this.height = this.tilemap.height * this.tilemap.tileSize;
        this.spawnPoint = levelData.spawnPoint;

        // Spawn entities from level data
        this.entities.clear();
        for (const entityData of levelData.entities) {
            this.entities.spawn(entityData.type, entityData.x, entityData.y);
        }
    }

    update(dt) {
        this.entities.update(dt, this);
        this.particles.update(dt);
    }

    // Check if a rect collides with solid tiles
    checkTileCollision(rect) {
        const tileSize = this.tilemap.tileSize;
        const startX = Math.floor(rect.x / tileSize);
        const endX = Math.floor((rect.x + rect.width) / tileSize);
        const startY = Math.floor(rect.y / tileSize);
        const endY = Math.floor((rect.y + rect.height) / tileSize);

        for (let y = startY; y <= endY; y++) {
            for (let x = startX; x <= endX; x++) {
                if (this.tilemap.isSolid(x, y)) {
                    return {
                        collided: true,
                        tileX: x,
                        tileY: y,
                        tileRect: {
                            x: x * tileSize,
                            y: y * tileSize,
                            width: tileSize,
                            height: tileSize
                        }
                    };
                }
            }
        }
        return { collided: false };
    }

    // Resolve collision and return corrected position
    resolveCollision(entity, newX, newY) {
        // Try horizontal movement
        entity.x = newX;
        let collision = this.checkTileCollision(entity.getBounds());
        if (collision.collided) {
            if (entity.vx > 0) {
                entity.x = collision.tileRect.x - entity.width;
            } else if (entity.vx < 0) {
                entity.x = collision.tileRect.x + collision.tileRect.width;
            }
            entity.vx = 0;
        }

        // Try vertical movement
        entity.y = newY;
        collision = this.checkTileCollision(entity.getBounds());
        if (collision.collided) {
            if (entity.vy > 0) {
                entity.y = collision.tileRect.y - entity.height;
                entity.grounded = true;
            } else if (entity.vy < 0) {
                entity.y = collision.tileRect.y + collision.tileRect.height;
            }
            entity.vy = 0;
        } else {
            entity.grounded = false;
        }
    }
}

// js/platformer/Player.js
export class Player {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.width = 32;
        this.height = 48;
        this.vx = 0;
        this.vy = 0;

        // Movement constants
        this.speed = 200;
        this.jumpForce = -450;
        this.gravity = 1200;
        this.maxFallSpeed = 600;
        this.friction = 0.85;
        this.airFriction = 0.95;

        // State
        this.grounded = false;
        this.facing = 1; // 1 = right, -1 = left
        this.state = 'idle'; // idle, run, jump, fall

        // Forgiving mechanics
        this.coyoteTime = 0.08; // seconds after leaving ground
        this.coyoteTimer = 0;
        this.jumpBufferTime = 0.1; // seconds before landing
        this.jumpBufferTimer = 0;

        // Visuals
        this.animTimer = 0;
        this.animFrame = 0;
    }

    update(dt, world, input) {
        // Horizontal movement
        if (input.isDown('ArrowRight') || input.isDown('KeyD')) {
            this.vx += this.speed * 2 * dt;
            this.facing = 1;
        } else if (input.isDown('ArrowLeft') || input.isDown('KeyA')) {
            this.vx -= this.speed * 2 * dt;
            this.facing = -1;
        }

        // Friction
        this.vx *= this.grounded ? this.friction : this.airFriction;

        // Clamp speed
        this.vx = Math.max(-this.speed, Math.min(this.vx, this.speed));

        // Gravity
        this.vy += this.gravity * dt;
        this.vy = Math.min(this.vy, this.maxFallSpeed);

        // Coyote time: can jump briefly after leaving ground
        if (this.grounded) {
            this.coyoteTimer = this.coyoteTime;
        } else {
            this.coyoteTimer -= dt;
        }

        // Jump buffering: store jump input before landing
        if (input.isPressed('Space') || input.isPressed('ArrowUp')) {
            this.jumpBufferTimer = this.jumpBufferTime;
        } else {
            this.jumpBufferTimer -= dt;
        }

        // Execute jump if buffered and coyote time active
        if (this.jumpBufferTimer > 0 && this.coyoteTimer > 0) {
            this.vy = this.jumpForce;
            this.grounded = false;
            this.coyoteTimer = 0;
            this.jumpBufferTimer = 0;
            world.particles.emit(this.x + this.width/2, this.y + this.height, 8, '#FFF');
        }

        // Variable jump height: release early for short hop
        if (!input.isDown('Space') && !input.isDown('ArrowUp') && this.vy < -200) {
            this.vy = -200;
        }

        // Predict next position
        const nextX = this.x + this.vx * dt;
        const nextY = this.y + this.vy * dt;

        // Resolve collision
        world.resolveCollision(this, nextX, nextY);

        // Update animation state
        this.updateState();
        this.updateAnimation(dt);
    }

    updateState() {
        if (!this.grounded) {
            this.state = this.vy < 0 ? 'jump' : 'fall';
        } else if (Math.abs(this.vx) > 10) {
            this.state = 'run';
        } else {
            this.state = 'idle';
        }
    }

    updateAnimation(dt) {
        this.animTimer += dt;
        const frameRate = this.state === 'run' ? 0.1 : 0.2;
        if (this.animTimer >= frameRate) {
            this.animTimer = 0;
            this.animFrame = (this.animFrame + 1) % this.getFrameCount();
        }
    }

    getFrameCount() {
        return { idle: 2, run: 4, jump: 1, fall: 1 }[this.state];
    }

    draw(ctx, alpha) {
        // Interpolate for smooth rendering between physics steps
        const drawX = this.x;
        const drawY = this.y;

        ctx.save();
        ctx.translate(drawX + this.width/2, drawY + this.height/2);
        ctx.scale(this.facing, 1);

        // Body
        ctx.fillStyle = '#3498db';
        ctx.fillRect(-this.width/2, -this.height/2, this.width, this.height);

        // Eyes (look direction)
        ctx.fillStyle = '#FFF';
        ctx.fillRect(4, -16, 8, 8);
        ctx.fillStyle = '#000';
        ctx.fillRect(8, -14, 4, 4);

        // State indicator (debug)
        // ctx.fillStyle = '#FFF';
        // ctx.font = '10px Arial';
        // ctx.fillText(this.state, -10, -30);

        ctx.restore();
    }

    getBounds() {
        return { x: this.x, y: this.y, width: this.width, height: this.height };
    }

    reset(x, y) {
        this.x = x;
        this.y = y;
        this.vx = 0;
        this.vy = 0;
        this.grounded = false;
    }
}

// js/platformer/EntityManager.js
export class EntityManager {
    constructor() {
        this.entities = [];
        this.toRemove = [];
    }

    clear() {
        this.entities = [];
    }

    spawn(type, x, y) {
        let entity;
        switch (type) {
            case 'slime': entity = new Slime(x, y); break;
            case 'goomba': entity = new Goomba(x, y); break;
            case 'coin': entity = new Coin(x, y); break;
            case 'flag': entity = new Flag(x, y); break;
        }
        if (entity) this.entities.push(entity);
    }

    update(dt, world) {
        for (const entity of this.entities) {
            entity.update(dt, world);

            // Check player collision
            if (entity.damage && this.checkOverlap(entity, world.player)) {
                world.player.takeDamage(entity.damage);
            }

            // Check stomp (player landing on enemy from above)
            if (entity.stompable && this.checkStomp(world.player, entity)) {
                entity.die();
                world.player.vy = -300; // Bounce
                world.particles.emit(entity.x + 16, entity.y, 15, '#0F0');
            }
        }

        // Remove dead entities
        this.entities = this.entities.filter(e => !e.dead);
    }

    checkOverlap(a, b) {
        return a.x < b.x + b.width && a.x + a.width > b.x &&
               a.y < b.y + b.height && a.y + a.height > b.y;
    }

    checkStomp(player, enemy) {
        return player.vy > 0 && // Falling
               player.y + player.height < enemy.y + enemy.height / 2 &&
               player.x + player.width > enemy.x &&
               player.x < enemy.x + enemy.width;
    }

    draw(ctx, camera) {
        for (const entity of this.entities) {
            if (entity.x + entity.width > camera.x && 
                entity.x < camera.x + camera.width) {
                entity.draw(ctx);
            }
        }
    }
}

// Base Enemy class
class Enemy {
    constructor(x, y, width, height) {
        this.x = x;
        this.y = y;
        this.width = width;
        this.height = height;
        this.vx = 0;
        this.vy = 0;
        this.dead = false;
        this.damage = 1;
        this.stompable = true;
    }

    die() {
        this.dead = true;
    }
}

class Slime extends Enemy {
    constructor(x, y) {
        super(x, y, 32, 24);
        this.patrolStart = x;
        this.patrolDist = 100;
        this.speed = 60;
        this.direction = 1;
        this.jumpTimer = 0;
        this.jumpInterval = 2;
    }

    update(dt, world) {
        // Patrol back and forth
        this.vx = this.speed * this.direction;
        this.x += this.vx * dt;

        // Turn at patrol boundaries or walls
        if (this.x > this.patrolStart + this.patrolDist ||
            world.checkTileCollision(this.getBounds()).collided) {
            this.direction *= -1;
        }

        // Gravity
        this.vy += 800 * dt;
        this.y += this.vy * dt;

        // Floor collision
        const floor = world.checkTileCollision(this.getBounds());
        if (floor.collided && this.vy > 0) {
            this.y = floor.tileRect.y - this.height;
            this.vy = 0;

            // Hop periodically
            this.jumpTimer += dt;
            if (this.jumpTimer >= this.jumpInterval) {
                this.vy = -250;
                this.jumpTimer = 0;
            }
        }
    }

    getBounds() {
        return { x: this.x, y: this.y, width: this.width, height: this.height };
    }

    draw(ctx) {
        ctx.fillStyle = '#2ecc71';
        ctx.beginPath();
        ctx.ellipse(this.x + 16, this.y + 12, 16, 12, 0, 0, Math.PI * 2);
        ctx.fill();

        // Eyes
        ctx.fillStyle = '#FFF';
        ctx.beginPath();
        ctx.arc(this.x + 10, this.y + 8, 4, 0, Math.PI * 2);
        ctx.arc(this.x + 22, this.y + 8, 4, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#000';
        ctx.beginPath();
        ctx.arc(this.x + 10 + this.direction * 2, this.y + 8, 2, 0, Math.PI * 2);
        ctx.arc(this.x + 22 + this.direction * 2, this.y + 8, 2, 0, Math.PI * 2);
        ctx.fill();
    }
}

class Coin {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.width = 20;
        this.height = 20;
        this.collected = false;
        this.bobOffset = Math.random() * Math.PI * 2;
    }

    update(dt, world) {
        this.bobOffset += dt * 3;

        if (!this.collected && world.player) {
            const dx = world.player.x - this.x;
            const dy = world.player.y - this.y;
            if (Math.hypot(dx, dy) < 30) {
                this.collected = true;
                world.player.coins++;
                world.particles.emit(this.x + 10, this.y + 10, 10, '#FFD700');
            }
        }
    }

    draw(ctx) {
        if (this.collected) return;
        const bobY = Math.sin(this.bobOffset) * 5;

        ctx.fillStyle = '#FFD700';
        ctx.beginPath();
        ctx.ellipse(this.x + 10, this.y + 10 + bobY, 8, 10, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#F39C12';
        ctx.lineWidth = 2;
        ctx.stroke();
    }
}

class ParticleEmitter {
    constructor(config = {}) {
        this.particles = [];
        this.config = {
            // Emission
            rate: 50,           // particles per second
            burst: 0,           // initial burst count
            maxParticles: 1000,

            // Lifetime
            lifetime: { min: 0.5, max: 1.5 },

            // Position
            position: { x: 0, y: 0 },
            spread: { x: 10, y: 10 },

            // Velocity
            speed: { min: 50, max: 150 },
            angle: { min: 0, max: Math.PI * 2 },
            gravity: { x: 0, y: 300 },

            // Appearance
            startColor: { r: 255, g: 200, b: 50, a: 1 },
            endColor: { r: 255, g: 50, b: 0, a: 0 },
            startSize: { min: 4, max: 8 },
            endSize: { min: 0, max: 2 },

            // Rotation
            rotationSpeed: { min: -2, max: 2 },

            // Blend mode
            additive: true,

            ...config
        };

        this.emissionTimer = 0;
        this.active = true;

        // Emit burst
        for (let i = 0; i < this.config.burst; i++) {
            this.emit();
        }
    }

    emit() {
        if (this.particles.length >= this.config.maxParticles) return;

        const cfg = this.config;
        const angle = this.rand(cfg.angle.min, cfg.angle.max);
        const speed = this.rand(cfg.speed.min, cfg.speed.max);

        this.particles.push({
            x: cfg.position.x + this.rand(-cfg.spread.x, cfg.spread.x),
            y: cfg.position.y + this.rand(-cfg.spread.y, cfg.spread.y),
            vx: Math.cos(angle) * speed,
            vy: Math.sin(angle) * speed,
            life: this.rand(cfg.lifetime.min, cfg.lifetime.max),
            maxLife: 0, // set below
            size: this.rand(cfg.startSize.min, cfg.startSize.max),
            endSize: this.rand(cfg.endSize.min, cfg.endSize.max),
            rotation: Math.random() * Math.PI * 2,
            rotSpeed: this.rand(cfg.rotationSpeed.min, cfg.rotationSpeed.max),
            color: { ...cfg.startColor }
        });

        const p = this.particles[this.particles.length - 1];
        p.maxLife = p.life;
    }

    update(dt) {
        // Continuous emission
        if (this.active && this.config.rate > 0) {
            this.emissionTimer += dt;
            const emitInterval = 1 / this.config.rate;
            while (this.emissionTimer >= emitInterval) {
                this.emit();
                this.emissionTimer -= emitInterval;
            }
        }

        // Update particles
        for (let i = this.particles.length - 1; i >= 0; i--) {
            const p = this.particles[i];
            p.life -= dt;

            if (p.life <= 0) {
                this.particles.splice(i, 1);
                continue;
            }

            const t = 1 - p.life / p.maxLife; // 0 to 1

            // Physics
            p.vx += this.config.gravity.x * dt;
            p.vy += this.config.gravity.y * dt;
            p.x += p.vx * dt;
            p.y += p.vy * dt;
            p.rotation += p.rotSpeed * dt;

            // Size interpolation
            p.size = this.lerp(p.size, p.endSize, dt * 3);

            // Color interpolation
            const c = this.config;
            p.color.r = this.lerp(c.startColor.r, c.endColor.r, t);
            p.color.g = this.lerp(c.startColor.g, c.endColor.g, t);
            p.color.b = this.lerp(c.startColor.b, c.endColor.b, t);
            p.color.a = this.lerp(c.startColor.a, c.endColor.a, t);
        }
    }

    draw(ctx) {
        ctx.save();
        if (this.config.additive) {
            ctx.globalCompositeOperation = 'lighter';
        }

        for (const p of this.particles) {
            ctx.save();
            ctx.translate(p.x, p.y);
            ctx.rotate(p.rotation);
            ctx.globalAlpha = Math.max(0, p.color.a);
            ctx.fillStyle = `rgb(${Math.round(p.color.r)},${Math.round(p.color.g)},${Math.round(p.color.b)})`;
            ctx.fillRect(-p.size / 2, -p.size / 2, p.size, p.size);
            ctx.restore();
        }

        ctx.restore();
    }

    rand(min, max) {
        return min + Math.random() * (max - min);
    }

    lerp(a, b, t) {
        return a + (b - a) * t;
    }
}

class TrailRenderer {
    constructor(maxLength = 20, width = 8) {
        this.points = [];
        this.maxLength = maxLength;
        this.width = width;
        this.color = { r: 100, g: 200, b: 255 };
    }

    addPoint(x, y) {
        this.points.push({ x, y, age: 0 });
        if (this.points.length > this.maxLength) {
            this.points.shift();
        }
    }

    update(dt) {
        for (const p of this.points) {
            p.age += dt;
        }
        // Remove old points
        this.points = this.points.filter(p => p.age < 0.5);
    }

    draw(ctx) {
        if (this.points.length < 2) return;

        ctx.save();
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        for (let i = 1; i < this.points.length; i++) {
            const p1 = this.points[i - 1];
            const p2 = this.points[i];
            const t = 1 - p2.age / 0.5;

            ctx.beginPath();
            ctx.moveTo(p1.x, p1.y);
            ctx.lineTo(p2.x, p2.y);
            ctx.strokeStyle = `rgba(${this.color.r},${this.color.g},${this.color.b},${t})`;
            ctx.lineWidth = this.width * t;
            ctx.stroke();
        }

        ctx.restore();
    }
}

