class SaveManager {
    constructor(gameVersion = '1.0.0') {
        this.version = gameVersion;
        this.prefix = 'mygame_';
        this.autoSaveInterval = 30; // seconds
        this.autoSaveTimer = 0;
        this.currentSlot = 0;
    }

    // Generate save data from game state
    createSaveData(world, player, stats) {
        return {
            version: this.version,
            timestamp: Date.now(),
            playTime: stats.totalPlayTime,
            slot: this.currentSlot,

            // World state
            level: world.currentLevel,
            entities: world.entities.getSaveData(),

            // Player state
            player: {
                x: player.x,
                y: player.y,
                health: player.health,
                maxHealth: player.maxHealth,
                coins: player.coins,
                score: player.score,
                upgrades: player.upgrades
            },

            // Settings
            settings: {
                volume: stats.volume,
                difficulty: stats.difficulty,
                controls: stats.controlMap
            }
        };
    }

    save(slot = this.currentSlot, data) {
        const key = `${this.prefix}save_${slot}`;
        const saveString = JSON.stringify(data);

        try {
            localStorage.setItem(key, saveString);
            localStorage.setItem(`${key}_meta`, JSON.stringify({
                date: new Date().toLocaleString(),
                playTime: data.playTime,
                level: data.level
            }));
            return true;
        } catch (e) {
            console.error('Save failed:', e);
            // Handle quota exceeded
            if (e.name === 'QuotaExceededError') {
                this.handleQuotaExceeded();
            }
            return false;
        }
    }

    load(slot = this.currentSlot) {
        const key = `${this.prefix}save_${slot}`;
        const saveString = localStorage.getItem(key);

        if (!saveString) return null;

        try {
            const data = JSON.parse(saveString);

            // Version migration
            if (data.version !== this.version) {
                return this.migrate(data);
            }

            return data;
        } catch (e) {
            console.error('Load failed:', e);
            return null;
        }
    }

    // List all save slots with metadata
    listSaves() {
        const saves = [];
        for (let i = 0; i < 5; i++) {
            const meta = localStorage.getItem(`${this.prefix}save_${i}_meta`);
            if (meta) {
                saves.push({ slot: i, ...JSON.parse(meta) });
            }
        }
        return saves;
    }

    delete(slot) {
        localStorage.removeItem(`${this.prefix}save_${slot}`);
        localStorage.removeItem(`${this.prefix}save_${slot}_meta`);
    }

    // Auto-save during gameplay
    update(dt, world, player, stats) {
        this.autoSaveTimer += dt;
        if (this.autoSaveTimer >= this.autoSaveInterval) {
            const data = this.createSaveData(world, player, stats);
            this.save(this.currentSlot, data);
            this.autoSaveTimer = 0;
            console.log('Auto-saved');
        }
    }

    // Handle storage full
    handleQuotaExceeded() {
        // Delete oldest saves or compress data
        const saves = this.listSaves();
        if (saves.length > 1) {
            saves.sort((a, b) => a.date - b.date);
            this.delete(saves[0].slot);
            console.log('Deleted oldest save to free space');
        }
    }

    // Migrate old save formats
    migrate(data) {
        console.log(`Migrating save from ${data.version} to ${this.version}`);

        // Example migrations
        if (data.version === '0.9.0') {
            // Add new fields with defaults
            data.player.upgrades = data.player.upgrades || {};
            data.settings = data.settings || { volume: 1, difficulty: 'normal' };
        }

        data.version = this.version;
        return data;
    }
}

class IndexedDBSaveManager {
    constructor(dbName = 'GameSaves', version = 1) {
        this.dbName = dbName;
        this.version = version;
        this.db = null;
    }

    async init() {
        return new Promise((resolve, reject) => {
            const request = indexedDB.open(this.dbName, this.version);

            request.onerror = () => reject(request.error);
            request.onsuccess = () => {
                this.db = request.result;
                resolve();
            };

            request.onupgradeneeded = (event) => {
                const db = event.target.result;
                if (!db.objectStoreNames.contains('saves')) {
                    db.createObjectStore('saves', { keyPath: 'slot' });
                }
                if (!db.objectStoreNames.contains('screenshots')) {
                    db.createObjectStore('screenshots', { keyPath: 'slot' });
                }
            };
        });
    }

    async save(slot, data, screenshot = null) {
        const transaction = this.db.transaction(['saves', 'screenshots'], 'readwrite');

        const saveStore = transaction.objectStore('saves');
        await saveStore.put({ slot, data, timestamp: Date.now() });

        if (screenshot) {
            const screenshotStore = transaction.objectStore('screenshots');
            // Convert canvas to blob
            const blob = await new Promise(resolve => screenshot.toBlob(resolve, 'image/png'));
            await screenshotStore.put({ slot, image: blob });
        }

        return new Promise((resolve, reject) => {
            transaction.oncomplete = () => resolve(true);
            transaction.onerror = () => reject(transaction.error);
        });
    }

    async load(slot) {
        return new Promise((resolve, reject) => {
            const transaction = this.db.transaction('saves', 'readonly');
            const store = transaction.objectStore('saves');
            const request = store.get(slot);

            request.onsuccess = () => resolve(request.result?.data || null);
            request.onerror = () => reject(request.error);
        });
    }

    async loadScreenshot(slot) {
        return new Promise((resolve, reject) => {
            const transaction = this.db.transaction('screenshots', 'readonly');
            const store = transaction.objectStore('screenshots');
            const request = store.get(slot);

            request.onsuccess = () => {
                if (request.result?.image) {
                    const url = URL.createObjectURL(request.result.image);
                    resolve(url);
                } else {
                    resolve(null);
                }
            };
            request.onerror = () => reject(request.error);
        });
    }
}

class SaveValidator {
    // Simple checksum for integrity
    static generateChecksum(data) {
        const str = JSON.stringify(data);
        let hash = 0;
        for (let i = 0; i < str.length; i++) {
            const char = str.charCodeAt(i);
            hash = ((hash << 5) - hash) + char;
            hash = hash & hash; // Convert to 32bit integer
        }
        return hash.toString(16);
    }

    static signSave(data, secret = 'your-game-secret') {
        const checksum = this.generateChecksum(data);
        // In production, use Web Crypto API for HMAC
        return btoa(checksum + secret);
    }

    static verifySave(data, signature, secret = 'your-game-secret') {
        const expected = this.signSave(data, secret);
        return signature === expected;
    }

    // Obfuscate scores to prevent easy editing
    static obfuscateScore(score) {
        // Simple XOR with key (easily cracked, just deters casual editing)
        const key = 0x5A;
        return (score ^ key).toString(16);
    }

    static deobfuscateScore(obfuscated) {
        const key = 0x5A;
        return parseInt(obfuscated, 16) ^ key;
    }
}

// Usage
const saveData = { level: 5, score: 10000 };
const signature = SaveValidator.signSave(saveData);
localStorage.setItem('save_data', JSON.stringify(saveData));
localStorage.setItem('save_sig', signature);

// On load
const loaded = JSON.parse(localStorage.getItem('save_data'));
const loadedSig = localStorage.getItem('save_sig');
if (!SaveValidator.verifySave(loaded, loadedSig)) {
    console.warn('Save file tampered with!');
    // Reset or show warning
}

class SaveFileIO {
    // Export save as downloadable file
    static exportSave(data, filename = 'save.json') {
        const blob = new Blob([JSON.stringify(data, null, 2)], 
            { type: 'application/json' });
        const url = URL.createObjectURL(blob);

        const a = document.createElement('a');
        a.href = url;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    }

    // Import save from file
    static importSave(file) {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = (e) => {
                try {
                    const data = JSON.parse(e.target.result);
                    resolve(data);
                } catch (err) {
                    reject(new Error('Invalid save file'));
                }
            };
            reader.onerror = () => reject(reader.error);
            reader.readAsText(file);
        });
    }

    // Create file input element
    static createImportInput(onImport) {
        const input = document.createElement('input');
        input.type = 'file';
        input.accept = '.json';
        input.style.display = 'none';

        input.onchange = async (e) => {
            const file = e.target.files[0];
            if (file) {
                try {
                    const data = await this.importSave(file);
                    onImport(data);
                } catch (err) {
                    alert('Failed to import: ' + err.message);
                }
            }
        };

        document.body.appendChild(input);
        input.click();
        document.body.removeChild(input);
    }
}

// Built-in performance markers
class PerformanceProfiler {
    constructor() {
        this.markers = new Map();
        this.frames = [];
        this.maxFrames = 60;
    }

    start(label) {
        performance.mark(`${label}-start`);
    }

    end(label) {
        performance.mark(`${label}-end`);
        performance.measure(label, `${label}-start`, `${label}-end`);

        const entries = performance.getEntriesByName(label);
        const last = entries[entries.length - 1];
        this.markers.set(label, last.duration);
    }

    frameStart() {
        this.start('frame');
    }

    frameEnd() {
        this.end('frame');
        const duration = this.markers.get('frame');
        this.frames.push(duration);
        if (this.frames.length > this.maxFrames) this.frames.shift();
    }

    getAverageFPS() {
        const avgFrame = this.frames.reduce((a, b) => a + b, 0) / this.frames.length;
        return Math.round(1000 / avgFrame);
    }

    drawDebug(ctx, x, y) {
        ctx.fillStyle = '#0F0';
        ctx.font = '12px monospace';
        let offset = 0;

        ctx.fillText(`FPS: ${this.getAverageFPS()}`, x, y);
        for (const [label, duration] of this.markers) {
            offset += 15;
            const color = duration > 16 ? '#F00' : '#0F0';
            ctx.fillStyle = color;
            ctx.fillText(`${label}: ${duration.toFixed(2)}ms`, x, y + offset);
        }
    }
}

// Usage in game loop
const profiler = new PerformanceProfiler();

function loop() {
    profiler.frameStart();

    profiler.start('update');
    update();
    profiler.end('update');

    profiler.start('draw');
    draw();
    profiler.end('draw');

    profiler.frameEnd();
    profiler.drawDebug(ctx, 10, 30);
}

class BatchedRenderer {
    constructor() {
        this.batches = new Map(); // texture -> array of draw calls
    }

    add(texture, sx, sy, sw, sh, dx, dy, dw, dh) {
        if (!this.batches.has(texture)) {
            this.batches.set(texture, []);
        }
        this.batches.get(texture).push({ sx, sy, sw, sh, dx, dy, dw, dh });
    }

    render(ctx) {
        for (const [texture, calls] of this.batches) {
            for (const c of calls) {
                ctx.drawImage(texture, c.sx, c.sy, c.sw, c.sh, c.dx, c.dy, c.dw, c.dh);
            }
        }
        this.batches.clear();
    }
}

