}

class SpatialHash {
    constructor(cellSize = 64) {
        this.cellSize = cellSize;
        this.cells = new Map(); // 'x,y' -> Set of entities
    }

    clear() {
        this.cells.clear();
    }

    insert(entity) {
        const bounds = entity.getBounds();
        const minX = Math.floor(bounds.x / this.cellSize);
        const maxX = Math.floor((bounds.x + bounds.width) / this.cellSize);
        const minY = Math.floor(bounds.y / this.cellSize);
        const maxY = Math.floor((bounds.y + bounds.height) / this.cellSize);

        for (let y = minY; y <= maxY; y++) {
            for (let x = minX; x <= maxX; x++) {
                const key = `${x},${y}`;
                if (!this.cells.has(key)) {
                    this.cells.set(key, new Set());
                }
                this.cells.get(key).add(entity);
            }
        }
    }

    query(entity) {
        const bounds = entity.getBounds();
        const minX = Math.floor(bounds.x / this.cellSize);
        const maxX = Math.floor((bounds.x + bounds.width) / this.cellSize);
        const minY = Math.floor(bounds.y / this.cellSize);
        const maxY = Math.floor((bounds.y + bounds.height) / this.cellSize);

        const results = new Set();
        for (let y = minY; y <= maxY; y++) {
            for (let x = minX; x <= maxX; x++) {
                const key = `${x},${y}`;
                const cell = this.cells.get(key);
                if (cell) {
                    for (const e of cell) {
                        if (e !== entity) results.add(e);
                    }
                }
            }
        }
        return Array.from(results);
    }
}

// Usage: O(n) collision instead of O(n²)
const hash = new SpatialHash(64);
for (const entity of entities) hash.insert(entity);

for (const entity of entities) {
    const nearby = hash.query(entity);
    for (const other of nearby) {
        if (checkCollision(entity, other)) {
            resolveCollision(entity, other);
        }
    }
}

class ObjectPool {
    constructor(createFn, resetFn, initialSize = 100) {
        this.createFn = createFn;
        this.resetFn = resetFn;
        this.available = [];
        this.inUse = [];

        // Pre-allocate
        for (let i = 0; i < initialSize; i++) {
            this.available.push(this.createFn());
        }
    }

    acquire(...args) {
        let obj = this.available.pop();
        if (!obj) {
            obj = this.createFn();
        }
        this.resetFn(obj, ...args);
        this.inUse.push(obj);
        return obj;
    }

    release(obj) {
        const index = this.inUse.indexOf(obj);
        if (index !== -1) {
            this.inUse.splice(index, 1);
            this.available.push(obj);
        }
    }

    releaseAll() {
        this.available.push(...this.inUse);
        this.inUse = [];
    }
}

