class PredictedPlayer {
    constructor() {
        this.x = 0;
        this.y = 0;
        this.vx = 0;
        this.vy = 0;

        // Server reconciliation
        this.serverX = 0;
        this.serverY = 0;
        this.pendingInputs = []; // Inputs not yet acknowledged
        this.inputSequence = 0;
    }

    update(dt, input) {
        // Apply input immediately (prediction)
        if (input.left) this.vx -= 1000 * dt;
        if (input.right) this.vx += 1000 * dt;
        if (input.jump && this.grounded) this.vy = -400;

        this.vx *= 0.85;
        this.vy += 800 * dt;

        this.x += this.vx * dt;
        this.y += this.vy * dt;

        // Queue input for server
        const inputData = {
            sequence: this.inputSequence++,
            left: input.left,
            right: input.right,
            jump: input.jump,
            dt: dt
        };
        this.pendingInputs.push(inputData);
        network.send('input', inputData);
    }

    // Called when server sends confirmed position
    reconcile(serverState) {
        this.serverX = serverState.x;
        this.serverY = serverState.y;

        // Remove acknowledged inputs
        this.pendingInputs = this.pendingInputs.filter(
            input => input.sequence > serverState.lastProcessedInput
        );

        // Rewind to server state
        this.x = this.serverX;
        this.y = this.serverY;

        // Re-apply unacknowledged inputs
        for (const input of this.pendingInputs) {
            this.applyInput(input);
        }
    }

    applyInput(input) {
        // Same physics as update() but without sending to server
        if (input.left) this.vx -= 1000 * input.dt;
        if (input.right) this.vx += 1000 * input.dt;
        if (input.jump && this.grounded) this.vy = -400;

        this.vx *= 0.85;
        this.vy += 800 * input.dt;

        this.x += this.vx * input.dt;
        this.y += this.vy * input.dt;
    }
}

class InterpolatedEntity {
    constructor() {
        this.positionBuffer = []; // { timestamp, x, y }
        this.renderX = 0;
        this.renderY = 0;
        this.interpolationDelay = 100; // ms behind
    }

    receiveUpdate(state) {
        this.positionBuffer.push({
            timestamp: Date.now(),
            x: state.x,
            y: state.y
        });

        // Keep only recent history
        const cutoff = Date.now() - 1000;
        this.positionBuffer = this.positionBuffer.filter(p => p.timestamp > cutoff);
    }

    update(dt) {
        const renderTime = Date.now() - this.interpolationDelay;

        // Find surrounding states
        let prev = null;
        let next = null;

        for (let i = 0; i < this.positionBuffer.length - 1; i++) {
            if (this.positionBuffer[i].timestamp <= renderTime &&
                this.positionBuffer[i + 1].timestamp >= renderTime) {
                prev = this.positionBuffer[i];
                next = this.positionBuffer[i + 1];
                break;
            }
        }

        if (prev && next) {
            const t = (renderTime - prev.timestamp) / (next.timestamp - prev.timestamp);
            this.renderX = prev.x + (next.x - prev.x) * t;
            this.renderY = prev.y + (next.y - prev.y) * t;
        } else if (prev) {
            this.renderX = prev.x;
            this.renderY = prev.y;
        }
    }

    draw(ctx) {
        ctx.fillStyle = '#E74C3C';
        ctx.fillRect(this.renderX - 16, this.renderY - 16, 32, 32);

        // Name tag
        ctx.fillStyle = '#FFF';
        ctx.font = '12px Arial';
        ctx.textAlign = 'center';
        ctx.fillText('Player 2', this.renderX, this.renderY - 24);
    }
}

// Server-side (Node.js with ws library)
const WebSocket = require('ws');
const wss = new WebSocket.Server({ port: 8080 });

class GameServer {
    constructor() {
        this.clients = new Map(); // ws -> player data
        this.gameState = {
            players: {},
            entities: []
        };
        this.tickRate = 60;
        this.lastTick = Date.now();
    }

    start() {
        setInterval(() => this.tick(), 1000 / this.tickRate);
    }

    tick() {
        const now = Date.now();
        const dt = (now - this.lastTick) / 1000;
        this.lastTick = now;

        // Update all players
        for (const [ws, player] of this.clients) {
            this.updatePlayer(player, dt);
        }

        // Update entities (projectiles, pickups)
        this.updateEntities(dt);

        // Check collisions
        this.checkCollisions();

        // Broadcast state to all clients
        this.broadcastState();
    }

    updatePlayer(player, dt) {
        // Apply pending inputs
        for (const input of player.inputs) {
            if (input.left) player.vx -= 1000 * input.dt;
            if (input.right) player.vx += 1000 * input.dt;
            if (input.jump && player.grounded) player.vy = -400;
        }
        player.inputs = []; // Clear processed

        // Physics (same as client for consistency)
        player.vx *= 0.85;
        player.vy += 800 * dt;

        const nextX = player.x + player.vx * dt;
        const nextY = player.y + player.vy * dt;

        // Server-side collision (authoritative!)
        if (this.isValidPosition(nextX, nextY)) {
            player.x = nextX;
            player.y = nextY;
        } else {
            player.vx = 0;
            player.vy = 0;
        }

        player.grounded = this.isOnGround(player);
    }

    isValidPosition(x, y) {
        // Check against level geometry
        // Reject if inside wall, out of bounds, or moved too far (speed hack)
        return x >= 0 && x < 2000 && y >= 0 && y < 1000;
    }

    broadcastState() {
        const state = {
            timestamp: Date.now(),
            players: {}
        };

        for (const [ws, player] of this.clients) {
            state.players[player.id] = {
                x: player.x,
                y: player.y,
                lastProcessedInput: player.lastProcessedInput
            };
        }

        const message = JSON.stringify({ type: 'state', data: state });
        for (const [ws] of this.clients) {
            ws.send(message);
        }
    }

    handleConnection(ws) {
        const player = {
            id: Math.random().toString(36).substr(2, 9),
            x: 100,
            y: 100,
            vx: 0,
            vy: 0,
            inputs: [],
            lastProcessedInput: -1
        };

        this.clients.set(ws, player);
        this.gameState.players[player.id] = player;

        ws.on('message', (data) => {
            const msg = JSON.parse(data);
            if (msg.type === 'input') {
                player.inputs.push(msg.data);
                player.lastProcessedInput = msg.data.sequence;
            }
        });

        ws.on('close', () => {
            this.clients.delete(ws);
            delete this.gameState.players[player.id];
        });

        // Send initial state
        ws.send(JSON.stringify({ type: 'init', data: { id: player.id } }));
    }
}

const server = new GameServer();
wss.on('connection', (ws) => server.handleConnection(ws));
server.start();

// Server-side lag compensation
class LagCompensator {
    constructor() {
        this.history = new Map(); // playerId -> [{timestamp, x, y}]
        this.maxHistory = 1000; // ms
    }

    recordState(playerId, x, y) {
        if (!this.history.has(playerId)) {
            this.history.set(playerId, []);
        }
        this.history.get(playerId).push({
            timestamp: Date.now(),
            x, y
        });
    }

    getHistoricalPosition(playerId, timestamp) {
        const states = this.history.get(playerId);
        if (!states) return null;

        // Find closest state to target time
        let closest = states[0];
        let minDiff = Infinity;

        for (const state of states) {
            const diff = Math.abs(state.timestamp - timestamp);
            if (diff < minDiff) {
                minDiff = diff;
                closest = state;
            }
        }

        return closest;
    }

    checkShot(shooter, targetId, shotTime, hitBox) {
        // Rewind target to when shooter fired
        const targetPos = this.getHistoricalPosition(targetId, shotTime);
        if (!targetPos) return false;

        // Check hit against historical position
        return this.aabb(
            { x: shooter.aimX, y: shooter.aimY, ...hitBox },
            { x: targetPos.x, y: targetPos.y, width: 32, height: 48 }
        );
    }
}

// js/shooter/Game.js
import { Player } from './Player.js';
import { BulletPool } from './BulletPool.js';
import { EnemyManager } from './EnemyManager.js';
import { WaveManager } from './WaveManager.js';
import { PowerUpManager } from './PowerUpManager.js';
import { ParticleManager } from './ParticleManager.js';
import { CameraShake } from './CameraShake.js';
import { CollisionSystem } from './CollisionSystem.js';
import { Starfield } from './Starfield.js';
import { HUD } from './HUD.js';

export class SpaceShooter {
    constructor(canvas) {
        this.canvas = canvas;
        this.ctx = canvas.getContext('2d');
        this.width = canvas.width;
        this.height = canvas.height;

        // Core systems
        this.bulletPool = new BulletPool(500);
        this.enemyManager = new EnemyManager(this);
        this.waveManager = new WaveManager(this);
        this.powerUpManager = new PowerUpManager();
        this.particleManager = new ParticleManager(1000);
        this.shake = new CameraShake();
        this.collision = new CollisionSystem();
        this.starfield = new Starfield(this.width, this.height);
        this.hud = new HUD(this.width, this.height);

        // Player
        this.player = new Player(this.width / 2, this.height - 100);

        // Game state
        this.score = 0;
        this.wave = 1;
        this.lives = 3;
        this.state = 'playing';
        this.slowMo = 1; // Time scale (0.3 for slow-mo)

        // Screen bounds for cleanup
        this.bounds = { left: -50, right: this.width + 50, top: -100, bottom: this.height + 100 };
    }

    start() {
        this.lastTime = performance.now();
        requestAnimationFrame((t) => this.loop(t));
    }

    loop(timestamp) {
        const rawDt = Math.min((timestamp - this.lastTime) / 1000, 0.1);
        this.lastTime = timestamp;
        const dt = rawDt * this.slowMo;

        this.update(dt, rawDt);
        this.draw();

        requestAnimationFrame((t) => this.loop(t));
    }

    update(dt, rawDt) {
        if (this.state !== 'playing') return;

        this.starfield.update(dt);
        this.player.update(dt, input);
        this.bulletPool.update(dt, this.bounds);
        this.enemyManager.update(dt, this.player);
        this.waveManager.update(dt);
        this.powerUpManager.update(dt, this.player);
        this.particleManager.update(dt);
        this.shake.update(rawDt);

        // Slow-mo decay
        this.slowMo += (1 - this.slowMo) * 5 * rawDt;

        this.collision.checkAll(this);
        this.cleanup();
    }

    draw() {
        // Clear with fade for motion blur effect
        this.ctx.fillStyle = 'rgba(5, 5, 15, 0.3)';
        this.ctx.fillRect(0, 0, this.width, this.height);

        this.ctx.save();
        this.shake.apply(this.ctx);

        this.starfield.draw(this.ctx);
        this.powerUpManager.draw(this.ctx);
        this.bulletPool.draw(this.ctx);
        this.enemyManager.draw(this.ctx);
        this.player.draw(this.ctx);
        this.particleManager.draw(this.ctx);

        this.ctx.restore();

        this.hud.draw(this.ctx, this.player, this.score, this.wave, this.lives);
    }

    addScore(points) {
        this.score += points * this.player.combo;
        this.player.combo = Math.min(this.player.combo + 1, 10);
        this.player.comboTimer = 2;
    }

    triggerSlowMo(duration = 0.5) {
        this.slowMo = 0.2;
    }

    spawnExplosion(x, y, color, count = 20) {
        this.particleManager.emit(x, y, count, color);
        this.shake.addTrauma(0.3);
    }
}

// js/shooter/BulletPool.js
class Bullet {
    constructor() {
        this.active = false;
        this.x = 0; this.y = 0;
        this.vx = 0; this.vy = 0;
        this.radius = 4;
        this.color = '#FFF';
        this.damage = 1;
        this.layer = 'enemy'; // 'player' or 'enemy'
        this.lifetime = 5;
    }

    reset(x, y, angle, speed, layer, color = '#FFF') {
        this.active = true;
        this.x = x;
        this.y = y;
        this.vx = Math.cos(angle) * speed;
        this.vy = Math.sin(angle) * speed;
        this.layer = layer;
        this.color = color;
        this.lifetime = 5;
    }
}

export class BulletPool {
    constructor(size) {
        this.bullets = Array.from({ length: size }, () => new Bullet());
        this.activeCount = 0;
    }

    spawn(x, y, angle, speed, layer, color) {
        const bullet = this.bullets.find(b => !b.active);
        if (bullet) {
            bullet.reset(x, y, angle, speed, layer, color);
            this.activeCount++;
        }
    }

    // Pattern: Spread shot (multiple angles)
    spawnSpread(x, y, baseAngle, count, spreadAngle, speed, layer, color) {
        const startAngle = baseAngle - spreadAngle / 2;
        const step = count > 1 ? spreadAngle / (count - 1) : 0;

        for (let i = 0; i < count; i++) {
            this.spawn(x, y, startAngle + step * i, speed, layer, color);
        }
    }

    // Pattern: Circle burst (all directions)
    spawnCircle(x, y, count, speed, layer, color) {
        const step = (Math.PI * 2) / count;
        for (let i = 0; i < count; i++) {
            this.spawn(x, y, step * i, speed, layer, color);
        }
    }

    // Pattern: Spiral
    spawnSpiral(x, y, count, speed, rotationSpeed, time, layer, color) {
        const baseAngle = time * rotationSpeed;
        const step = (Math.PI * 2) / count;
        for (let i = 0; i < count; i++) {
            this.spawn(x, y, baseAngle + step * i, speed, layer, color);
        }
    }

    // Pattern: Aimed at target
    spawnAimed(x, y, targetX, targetY, speed, layer, color) {
        const angle = Math.atan2(targetY - y, targetX - x);
        this.spawn(x, y, angle, speed, layer, color);
    }

    update(dt, bounds) {
        this.activeCount = 0;
        for (const b of this.bullets) {
            if (!b.active) continue;

            b.x += b.vx * dt;
            b.y += b.vy * dt;
            b.lifetime -= dt;

            if (b.lifetime <= 0 ||
                b.x < bounds.left || b.x > bounds.right ||
                b.y < bounds.top || b.y > bounds.bottom) {
                b.active = false;
            } else {
                this.activeCount++;
            }
        }
    }

    draw(ctx) {
        for (const b of this.bullets) {
            if (!b.active) continue;

            ctx.fillStyle = b.color;
            ctx.beginPath();
            ctx.arc(b.x, b.y, b.radius, 0, Math.PI * 2);
            ctx.fill();

            // Glow for enemy bullets
            if (b.layer === 'enemy') {
                ctx.shadowColor = b.color;
                ctx.shadowBlur = 10;
                ctx.fill();
                ctx.shadowBlur = 0;
            }
        }
    }

    getActive() {
        return this.bullets.filter(b => b.active);
    }
}

// js/shooter/Enemy.js
class Enemy {
    constructor(x, y, config) {
        this.x = x;
        this.y = y;
        this.vx = 0;
        this.vy = 0;
        this.active = true;
        this.health = config.health || 10;
        this.maxHealth = this.health;
        this.radius = config.radius || 20;
        this.score = config.score || 100;
        this.color = config.color || '#E74C3C';

        // Components
        this.movement = config.movement || new StraightMovement(0, 100);
        this.shooter = config.shooter || null;
        this.loot = config.loot || null;

        this.time = 0;
    }

    update(dt, player, bulletPool) {
        this.time += dt;

        // Movement
        this.movement.update(this, dt, player);

        // Shooting
        if (this.shooter) {
            this.shooter.update(this, dt, player, bulletPool);
        }

        // Bounds check
        if (this.y > 700 || this.y < -100 || this.x < -100 || this.x > 900) {
            this.active = false;
        }
    }

    takeDamage(damage) {
        this.health -= damage;
        if (this.health <= 0) {
            this.active = false;
            return true; // Died
        }
        return false;
    }

    draw(ctx) {
        ctx.save();
        ctx.translate(this.x, this.y);

        // Body
        ctx.fillStyle = this.color;
        ctx.beginPath();
        ctx.moveTo(0, -this.radius);
        ctx.lineTo(this.radius, this.radius);
        ctx.lineTo(-this.radius, this.radius);
        ctx.closePath();
        ctx.fill();

        // Health bar
        if (this.health < this.maxHealth) {
            ctx.fillStyle = '#333';
            ctx.fillRect(-20, -this.radius - 10, 40, 4);
            ctx.fillStyle = '#0F0';
            ctx.fillRect(-20, -this.radius - 10, 40 * (this.health / this.maxHealth), 4);
        }

        ctx.restore();
    }
}

// Movement components
class StraightMovement {
    constructor(angle, speed) {
        this.angle = angle;
        this.speed = speed;
    }
    update(enemy, dt) {
        enemy.x += Math.cos(this.angle) * this.speed * dt;
        enemy.y += Math.sin(this.angle) * this.speed * dt;
    }
}

class SineMovement {
    constructor(speed, amplitude, frequency) {
        this.speed = speed;
        this.amplitude = amplitude;
        this.frequency = frequency;
        this.baseX = 0;
    }
    update(enemy, dt) {
        if (this.baseX === 0) this.baseX = enemy.x;
        enemy.y += this.speed * dt;
        enemy.x = this.baseX + Math.sin(enemy.y * this.frequency) * this.amplitude;
    }
}

class HomingMovement {
    constructor(speed, turnRate) {
        this.speed = speed;
        this.turnRate = turnRate;
    }
    update(enemy, dt, player) {
        const desiredAngle = Math.atan2(player.y - enemy.y, player.x - enemy.x);
        let angleDiff = desiredAngle - Math.atan2(enemy.vy || 1, enemy.vx || 0);

        // Normalize to -PI to PI
        while (angleDiff > Math.PI) angleDiff -= Math.PI * 2;
        while (angleDiff < -Math.PI) angleDiff += Math.PI * 2;

        const turn = Math.max(-this.turnRate * dt, Math.min(this.turnRate * dt, angleDiff));
        const currentAngle = Math.atan2(enemy.vy || 1, enemy.vx || 0) + turn;

        enemy.vx = Math.cos(currentAngle) * this.speed;
        enemy.vy = Math.sin(currentAngle) * this.speed;
        enemy.x += enemy.vx * dt;
        enemy.y += enemy.vy * dt;
    }
}

// Shooter components
class BurstShooter {
    constructor(interval, bulletSpeed, count) {
        this.interval = interval;
        this.bulletSpeed = bulletSpeed;
        this.count = count;
        this.timer = 0;
    }
    update(enemy, dt, player, bulletPool) {
        this.timer += dt;
        if (this.timer >= this.interval) {
            this.timer = 0;
            bulletPool.spawnAimed(
                enemy.x, enemy.y, player.x, player.y,
                this.bulletSpeed, 'enemy', '#F39C12'
            );
        }
    }
}

class CircleShooter {
    constructor(interval, bulletSpeed, count) {
        this.interval = interval;
        this.bulletSpeed = bulletSpeed;
        this.count = count;
        this.timer = 0;
    }
    update(enemy, dt, player, bulletPool) {
        this.timer += dt;
        if (this.timer >= this.interval) {
            this.timer = 0;
            bulletPool.spawnCircle(
                enemy.x, enemy.y, this.count,
                this.bulletSpeed, 'enemy', '#E74C3C'
            );
        }
    }
}

// Enemy factory
export class EnemyFactory {
    static createGrunt(x, y) {
        return new Enemy(x, y, {
            health: 10,
            score: 100,
            color: '#E74C3C',
            movement: new StraightMovement(Math.PI / 2, 150),
            shooter: new BurstShooter(1.5, 200, 1)
        });
