    static createSineFighter(x, y) {
        return new Enemy(x, y, {
            health: 15,
            score: 200,
            color: '#9B59B6',
            movement: new SineMovement(100, 100, 0.01),
            shooter: new BurstShooter(2, 250, 3)
        });
    }

    static createKamikaze(x, y) {
        return new Enemy(x, y, {
            health: 5,
            score: 150,
            color: '#F39C12',
