}

// js/shooter/WaveManager.js
export class WaveManager {
    constructor(game) {
        this.game = game;
        this.waves = this.loadWaves();
        this.currentWave = 0;
        this.waveTimer = 0;
        this.spawnQueue = [];
        this.waveActive = false;
    }

    loadWaves() {
        return [
            { // Wave 1: Basic grunts
                duration: 15,
                spawns: [
                    { time: 0, type: 'grunt', x: 200 },
                    { time: 2, type: 'grunt', x: 400 },
                    { time: 2, type: 'grunt', x: 600 },
                    { time: 5, type: 'grunt', x: 300 },
                    { time: 5, type: 'grunt', x: 500 },
                    { time: 8, type: 'sine', x: 100 },
                    { time: 8, type: 'sine', x: 700 }
                ]
            },
            { // Wave 2: Kamikazes
                duration: 20,
                spawns: [
                    { time: 0, type: 'kamikaze', x: 100 },
                    { time: 0.5, type: 'kamikaze', x: 200 },
                    { time: 1, type: 'kamikaze', x: 300 },
                    { time: 5, type: 'grunt', x: 400 },
                    { time: 10, type: 'kamikaze', x: 150 },
                    { time: 10.5, type: 'kamikaze', x: 350 },
                    { time: 11, type: 'kamikaze', x: 550 },
                    { time: 11.5, type: 'kamikaze', x: 650 }
                ]
            },
            { // Wave 3: Boss
                duration: 60,
                spawns: [
                    { time: 5, type: 'boss', x: 400 },
                    { time: 10, type: 'grunt', x: 100 },
                    { time: 10, type: 'grunt', x: 700 },
                    { time: 20, type: 'kamikaze', x: 200 },
                    { time: 20, type: 'kamikaze', x: 600 }
                ]
            }
        ];
    }

    update(dt) {
        if (!this.waveActive) {
            this.startWave();
            return;
        }

        this.waveTimer += dt;
        const wave = this.waves[this.currentWave];

        // Process spawn queue
        while (this.spawnQueue.length > 0 && this.spawnQueue[0].time <= this.waveTimer) {
            const spawn = this.spawnQueue.shift();
            this.spawnEnemy(spawn);
        }

        // Check wave completion
        if (this.waveTimer >= wave.duration && this.game.enemyManager.count() === 0) {
            this.completeWave();
        }
    }

    startWave() {
        if (this.currentWave >= this.waves.length) {
            this.game.state = 'victory';
            return;
        }

        const wave = this.waves[this.currentWave];
        this.spawnQueue = [...wave.spawns].sort((a, b) => a.time - b.time);
        this.waveTimer = 0;
        this.waveActive = true;
        this.game.wave = this.currentWave + 1;

        // Wave announcement
        this.game.hud.showMessage(`WAVE ${this.currentWave + 1}`);
    }

    spawnEnemy(spawn) {
        const enemy = EnemyFactory[`create${spawn.type.charAt(0).toUpperCase() + spawn.type.slice(1)}`](spawn.x, -50);
        this.game.enemyManager.add(enemy);
    }

    completeWave() {
        this.waveActive = false;
        this.currentWave++;

        // Bonus score
        this.game.addScore(1000);
        this.game.hud.showMessage('WAVE CLEAR!');
    }
}

// js/shooter/CollisionSystem.js
export class CollisionSystem {
    checkAll(game) {
        const player = game.player;
        const bullets = game.bulletPool.getActive();
        const enemies = game.enemyManager.getActive();
        const powerUps = game.powerUpManager.getActive();

        // Player bullets vs enemies
        for (const bullet of bullets) {
            if (bullet.layer !== 'player') continue;

            for (const enemy of enemies) {
                if (!enemy.active) continue;

                if (this.circleCollision(bullet, enemy)) {
                    bullet.active = false;
                    if (enemy.takeDamage(bullet.damage)) {
                        game.spawnExplosion(enemy.x, enemy.y, enemy.color, 30);
                        game.addScore(enemy.score);

                        // Drop power-up chance
                        if (Math.random() < 0.1) {
                            game.powerUpManager.spawn(enemy.x, enemy.y);
                        }
                    }
                    break;
                }
            }
        }

        // Enemy bullets vs player
        for (const bullet of bullets) {
            if (bullet.layer !== 'enemy') continue;

            if (this.circleCollision(bullet, player)) {
                bullet.active = false;
                if (player.takeDamage(bullet.damage)) {
                    game.lives--;
                    game.spawnExplosion(player.x, player.y, '#3498DB', 50);
                    game.triggerSlowMo();

                    if (game.lives <= 0) {
                        game.state = 'gameover';
                    } else {
                        player.respawn();
                    }
                }
                break;
            }
        }

        // Enemies vs player (crash)
        for (const enemy of enemies) {
            if (this.circleCollision(enemy, player)) {
                enemy.active = false;
                game.spawnExplosion(enemy.x, enemy.y, enemy.color, 20);

                if (player.takeDamage(20)) {
                    game.lives--;
                    if (game.lives <= 0) game.state = 'gameover';
                }
            }
        }

        // Power-ups vs player
        for (const powerUp of powerUps) {
            if (this.circleCollision(powerUp, player)) {
                powerUp.collect(player);
                game.hud.showMessage(powerUp.name);
            }
        }
    }

    circleCollision(a, b) {
        const dx = a.x - b.x;
        const dy = a.y - b.y;
        const dist = Math.hypot(dx, dy);
        const radiusA = a.radius || 4;
        const radiusB = b.radius || 20;
        return dist < radiusA + radiusB;
    }
}

class VirtualJoystick {
    constructor(x, y, radius = 60) {
        this.baseX = x;
        this.baseY = y;
        this.radius = radius;
        this.knobRadius = 25;
        this.touchId = null;
        this.knobX = x;
        this.knobY = y;
        this.value = { x: 0, y: 0 }; // Normalized -1 to 1
        this.active = false;
    }

    handleTouchStart(touches) {
        for (const touch of touches) {
            const dx = touch.clientX - this.baseX;
            const dy = touch.clientY - this.baseY;

            if (Math.hypot(dx, dy) < this.radius * 1.5 && this.touchId === null) {
                this.touchId = touch.identifier;
                this.active = true;
                this.updateKnob(touch.clientX, touch.clientY);
                return true;
            }
        }
        return false;
    }

    handleTouchMove(touches) {
        for (const touch of touches) {
            if (touch.identifier === this.touchId) {
                this.updateKnob(touch.clientX, touch.clientY);
                return true;
            }
        }
        return false;
    }

    handleTouchEnd(touches) {
        // Check if our touch was released
        const stillActive = Array.from(touches).some(t => t.identifier === this.touchId);
        if (!stillActive && this.touchId !== null) {
            this.touchId = null;
            this.active = false;
            this.knobX = this.baseX;
            this.knobY = this.baseY;
            this.value = { x: 0, y: 0 };
        }
    }

    updateKnob(touchX, touchY) {
        const dx = touchX - this.baseX;
        const dy = touchY - this.baseY;
        const dist = Math.hypot(dx, dy);
        const maxDist = this.radius - this.knobRadius;

        if (dist > maxDist) {
            const ratio = maxDist / dist;
            this.knobX = this.baseX + dx * ratio;
            this.knobY = this.baseY + dy * ratio;
        } else {
            this.knobX = touchX;
            this.knobY = touchY;
        }

        // Normalize output
        this.value.x = Math.max(-1, Math.min(1, dx / maxDist));
        this.value.y = Math.max(-1, Math.min(1, dy / maxDist));
    }

    draw(ctx) {
        if (!this.active) return;

        // Base
        ctx.globalAlpha = 0.3;
        ctx.fillStyle = '#FFF';
        ctx.beginPath();
        ctx.arc(this.baseX, this.baseY, this.radius, 0, Math.PI * 2);
        ctx.fill();

        // Knob
        ctx.globalAlpha = 0.6;
        ctx.fillStyle = '#3498DB';
        ctx.beginPath();
        ctx.arc(this.knobX, this.knobY, this.knobRadius, 0, Math.PI * 2);
        ctx.fill();

        ctx.globalAlpha = 1;
    }
}

class ResponsiveCanvas {
    constructor(canvas, gameWidth, gameHeight) {
        this.canvas = canvas;
        this.gameWidth = gameWidth;
        this.gameHeight = gameHeight;
        this.scale = 1;
        this.offsetX = 0;
        this.offsetY = 0;

        window.addEventListener('resize', () => this.resize());
        window.addEventListener('orientationchange', () => this.resize());
        this.resize();
    }

    resize() {
        const windowWidth = window.innerWidth;
        const windowHeight = window.innerHeight;
        const gameRatio = this.gameWidth / this.gameHeight;
        const windowRatio = windowWidth / windowHeight;

        let renderWidth, renderHeight;

        if (windowRatio > gameRatio) {
            // Window is wider — fit to height
            renderHeight = windowHeight;
            renderWidth = renderHeight * gameRatio;
        } else {
            // Window is taller — fit to width
            renderWidth = windowWidth;
            renderHeight = renderWidth / gameRatio;
        }

        this.scale = renderWidth / this.gameWidth;
        this.offsetX = (windowWidth - renderWidth) / 2;
        this.offsetY = (windowHeight - renderHeight) / 2;

        // Set display size
        this.canvas.style.width = renderWidth + 'px';
        this.canvas.style.height = renderHeight + 'px';
        this.canvas.style.left = this.offsetX + 'px';
        this.canvas.style.top = this.offsetY + 'px';
        this.canvas.style.position = 'absolute';

        // Set actual resolution (with DPI scaling)
        const dpr = window.devicePixelRatio || 1;
        this.canvas.width = this.gameWidth * dpr;
        this.canvas.height = this.gameHeight * dpr;

        const ctx = this.canvas.getContext('2d');
        ctx.scale(dpr, dpr);
    }

    // Convert screen touch to game coordinates
    screenToGame(screenX, screenY) {
        return {
            x: (screenX - this.offsetX) / this.scale,
            y: (screenY - this.offsetY) / this.scale
        };
    }
}

class TouchButton {
    constructor(x, y, radius, label, onPress, onRelease) {
        this.x = x;
        this.y = y;
        this.radius = radius;
        this.label = label;
        this.onPress = onPress;
        this.onRelease = onRelease;
        this.pressed = false;
        this.touchId = null;
        this.pressScale = 1;
    }

    handleTouchStart(touches) {
        for (const touch of touches) {
            const pos = responsiveCanvas.screenToGame(touch.clientX, touch.clientY);
            const dist = Math.hypot(pos.x - this.x, pos.y - this.y);

            if (dist < this.radius && this.touchId === null) {
                this.touchId = touch.identifier;
                this.pressed = true;
                this.pressScale = 0.9;
                this.onPress?.();

                // Haptic feedback
                if (navigator.vibrate) {
                    navigator.vibrate(15);
                }
                return true;
            }
        }
        return false;
    }

    handleTouchEnd(touches) {
        const stillActive = Array.from(touches).some(t => t.identifier === this.touchId);
        if (!stillActive && this.touchId !== null) {
            this.touchId = null;
            this.pressed = false;
            this.pressScale = 1;
            this.onRelease?.();
        }
    }

    update(dt) {
        // Animate press
        const target = this.pressed ? 0.9 : 1;
        this.pressScale += (target - this.pressScale) * 15 * dt;
    }

    draw(ctx) {
        ctx.save();
        ctx.translate(this.x, this.y);
        ctx.scale(this.pressScale, this.pressScale);

        // Button circle
        ctx.fillStyle = this.pressed ? 'rgba(52, 152, 219, 0.8)' : 'rgba(52, 152, 219, 0.4)';
        ctx.beginPath();
        ctx.arc(0, 0, this.radius, 0, Math.PI * 2);
        ctx.fill();

        // Border
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.6)';
        ctx.lineWidth = 3;
        ctx.stroke();

        // Label
        ctx.fillStyle = '#FFF';
        ctx.font = `bold ${this.radius * 0.5}px Arial`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(this.label, 0, 0);

        ctx.restore();
    }
}

class MobileOptimizer {
    constructor() {
        this.isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
        this.batterySave = false;

        // Detect battery status
        if ('getBattery' in navigator) {
            navigator.getBattery().then(battery => {
                this.batterySave = battery.level < 0.2;
                battery.addEventListener('levelchange', () => {
                    this.batterySave = battery.level < 0.2;
                });
            });
        }
    }

    getParticleLimit() {
        return this.isMobile ? (this.batterySave ? 100 : 300) : 1000;
    }

    getTargetFPS() {
        // Cap at 30 FPS on low battery
        return this.batterySave ? 30 : 60;
    }

    shouldUseSimpleEffects() {
        return this.isMobile || this.batterySave;
    }

    // Pause when tab is hidden (saves battery)
    setupVisibilityHandling(game) {
        document.addEventListener('visibilitychange', () => {
            if (document.hidden) {
                game.pause();
            } else {
                game.resume();
            }
        });
    }
}

// Disable context menu on long press
document.addEventListener('contextmenu', e => e.preventDefault());

// Prevent zoom on double tap
let lastTouchEnd = 0;
document.addEventListener('touchend', (e) => {
    const now = Date.now();
    if (now - lastTouchEnd <= 300) {
        e.preventDefault();
    }
    lastTouchEnd = now;
}, false);
